window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-2/pbe","titre":"Pratique fondée sur les preuves","sources":[{"t":"Références bibliographiques et checklists","q":"annexes-references-bibliographiques/quiz.html","f":"annexes-references-bibliographiques/fiche.html"},{"t":"Science, méthode scientifique et questions cliniques","q":"cours-01-science-et-questions-cliniques/quiz.html","f":"cours-01-science-et-questions-cliniques/fiche.html"},{"t":"Les étapes du processus de recherche","q":"cours-03-etapes-du-processus-de-recherche/quiz.html","f":"cours-03-etapes-du-processus-de-recherche/fiche.html"},{"t":"Types d'études : les études primaires","q":"cours-04-etudes-primaires/quiz.html","f":"cours-04-etudes-primaires/fiche.html"},{"t":"Les études secondaires","q":"cours-05-etudes-secondaires/quiz.html","f":"cours-05-etudes-secondaires/fiche.html"},{"t":"Méthodes d'évaluation des résultats et validation d'instruments","q":"cours-06-methodes-evaluation-et-validation/quiz.html","f":"cours-06-methodes-evaluation-et-validation/fiche.html"},{"t":"Pratique fondée sur l'évidence et pratique informée par l'évidence","q":"cours-08-pbe-et-pie/quiz.html","f":"cours-08-pbe-et-pie/fiche.html"},{"t":"Statistiques et biostatistique","q":"cours-09-statistiques/quiz.html","f":"cours-09-statistiques/fiche.html"}],"questions":[{"q":"Quelle checklist s'applique au rapport d'un essai contrôlé randomisé ?","o":["CONSORT","STROBE","PRISMA","CARE"],"r":0,"e":"CONSORT est la checklist de référence pour rapporter un essai clinique randomisé.","s":0},{"q":"Quelle checklist s'applique aux études observationnelles ?","o":["CONSORT","STROBE","SQUIRE","AGREE"],"r":1,"e":"STROBE concerne les études observationnelles : cohorte, cas-témoins et transversales.","s":0},{"q":"Quelle checklist s'applique aux revues systématiques et méta-analyses ?","o":["PRISMA","CONSORT","CARE","TREND"],"r":0,"e":"PRISMA 2020, avec sa checklist et son diagramme de flux, sert à rapporter les revues systématiques et méta-analyses.","s":0},{"q":"Quelle checklist s'applique aux rapports de cas cliniques ?","o":["STROBE","CARE","SQUIRE","AGREE"],"r":1,"e":"CARE structure le rapport de cas clinique : informations du patient, chronologie, examens, interventions, résultats, perspective du patient et consentement.","s":0},{"q":"Quelle checklist concerne les études d'intervention NON randomisées ?","o":["CONSORT","TREND","PRISMA","COSMIN"],"r":1,"e":"TREND comble l'angle mort de CONSORT pour les études d'intervention non randomisées.","s":0},{"q":"Quelle checklist concerne les études d'amélioration de la qualité des soins ?","o":["SQUIRE","AGREE","STROBE","CARE"],"r":0,"e":"SQUIRE 2.0 sert à rapporter les études d'amélioration de la qualité : contexte, intervention, mesures de processus et de résultat. Dans sa version 2.0.","s":0},{"q":"À quoi sert l'outil AGREE ?","o":["À évaluer la qualité méthodologique d'une guideline","À rapporter un essai randomisé, contrôlé","À sélectionner un instrument de mesure","À enregistrer le protocole d'une revue systématique, en ligne"],"r":0,"e":"AGREE évalue la qualité méthodologique d'une norme d'orientation clinique : champ, participation des parties prenantes, rigueur d'élaboration, clarté, applicabilité, indépendance éditoriale.","s":0},{"q":"Que contient le diagramme de flux PRISMA ?","o":["Les études identifiées, filtrées, éligibles, incluses","Le calendrier de l'étude, de l'inclusion jusqu'au suivi","La répartition des participants entre groupes","La courbe des résultats, au fil du temps"],"r":0,"e":"Le diagramme de flux PRISMA retrace la sélection : identifiés, filtrés, éligibles, inclus, avec les motifs d'exclusion. Les motifs d'exclusion y figurent aussi.","s":0},{"q":"À quoi sert la guideline COSMIN ?","o":["À rapporter un essai randomisé, avec son diagramme de flux","À choisir les instruments d'un Core Outcome Set","À adapter une échelle à une autre culture","À enregistrer une revue systématique"],"r":1,"e":"COSMIN est la guideline de sélection des instruments de mesure des résultats, notamment pour constituer un Core Outcome Set. Il s'agit des instruments de mesure des résultats.","s":0},{"q":"Combien d'étapes compte le processus d'adaptation transculturelle de Beaton et al. (2000) ?","o":["3","4","6","9"],"r":2,"e":"Le processus compte 6 étapes : traduction, synthèse, rétrotraduction, comité d'experts, pré-test et envoi du matériel aux auteurs originaux.","s":0},{"q":"Quels sont les trois critères obligatoires de l'adaptation transculturelle ?","o":["Équivalences conceptuelle et sémantique, psychométrie","Traduction, rétrotraduction et publication finale","Validité, fiabilité et coût de passation","Langue, culture et contexte du pays"],"r":0,"e":"Les critères obligatoires sont l'équivalence conceptuelle, l'équivalence sémantique et les propriétés psychométriques (validité, fiabilité). Les propriétés psychométriques sont la validité et la fiabilité.","s":0},{"q":"Combien d'étapes compte la méthodologie d'une scoping review ?","o":["3","5","6","9"],"r":1,"e":"La scoping review suit 5 étapes : identifier la question, définir la stratégie de recherche, sélectionner les études, cartographier l'information et décrire sommairement les résultats.","s":0},{"q":"Quelle différence fondamentale sépare scoping review et revue systématique ?","o":["La scoping cartographie, la systématique évalue les biais","La scoping est plus longue, la systématique plus rapide","La systématique n'a pas de critères d'éligibilité définis","Aucune, les deux termes sont interchangeables en pratique"],"r":0,"e":"La scoping review cartographie un sujet large sans évaluer la qualité des études ; la revue systématique répond à une question ciblée et évalue la qualité méthodologique et le risque de biais. La scoping review n'évalue pas la qualité des études ; la revue systématique répond à une question ciblée.","s":0},{"q":"Quel rôle préliminaire peut jouer une scoping review ?","o":["Remplacer définitivement la revue systématique","Juger de la faisabilité d'une revue systématique","Fournir une méta-analyse rapide, sans protocole","Valider un instrument de mesure, avant son adaptation"],"r":1,"e":"La scoping review peut être un exercice préliminaire à la revue systématique, qui en affine la question. Elle aide aussi à juger de sa pertinence et à affiner la question.","s":0},{"q":"Sur quelle plateforme enregistre-t-on le titre d'une revue systématique ?","o":["PROSPERO","PRISMA","Rayyan","COMET"],"r":0,"e":"L'enregistrement du titre d'une revue systématique se fait sur PROSPERO.","s":0},{"q":"Que signifie le A de la grille FAITH ?","o":["Ont-ils analysé les statistiques ?","Ont-ils évalué chaque étude ?","Ont-ils appliqué les résultats à la pratique ?","Ont-ils accepté les conclusions des auteurs ?"],"r":1,"e":"Le A de FAITH demande si les auteurs ont évalué les études individuellement, ce qui renvoie à l'usage du RAMBOMAN. L'évaluation individuelle des études se fait avec le RAMBOMAN.","s":0},{"q":"Que couvre l'acronyme RAMBOMAN ?","o":["Recrutement, Allocation, Maintien, Blinding, Objectif, Mesures, ANalyse","Revue, Article, Méthode, Biais, Outcome, Mesure, Analyse","Randomisation, Aveuglement, Mesure, Biais, Objectif, Méthode, Analyse","Rapport, Adaptation, Méthode, Bilan, Objectif, Modèle, Analyse"],"r":0,"e":"RAMBOMAN = Recrutement, Allocation, Maintien, Aveuglement/dissimulation, Objectif, Mesures, ANalyse. Le B correspond à l'aveuglement (blinding) et à la dissimulation.","s":0},{"q":"Que change la « nouvelle pyramide » de l'évidence ?","o":["Elle supprime les études observationnelles","Les revues deviennent la lentille des études primaires","Elle met les avis d'experts au sommet de la pyramide","Elle classe les études par date de publication"],"r":1,"e":"Dans la nouvelle pyramide, les revues systématiques ne sont plus un simple étage supérieur mais la lentille de lecture des études primaires, et les frontières entre niveaux deviennent moins rigides. Les frontières entre étages deviennent moins rigides.","s":0},{"q":"Quel est l'apport principal des données de vie réelle ?","o":["Une validité interne élevée, contrôlée","Une validité externe élevée, pour l'effectivité","Une randomisation plus rigoureuse, en double aveugle","Un coût plus élevé, par patient"],"r":1,"e":"Les real world studies ont une validité externe élevée et une validité interne basse : elles répondent à la question de l'effectivité, là où les ECR répondent à l'efficacité.","s":0},{"q":"Quelle phrase résume le rapport entre ECR et données de vie réelle ?","o":["L'efficacité ne se traduit pas toujours en effectivité","Les essais randomisés restent supérieurs, en toute situation","La vie réelle remplace les essais randomisés","Les deux mesurent exactement la même chose"],"r":0,"e":"Le cours conclut que l'efficacité, propriété intrinsèque démontrée par les ECR, ne se traduit pas toujours en effectivité, mesurée par les real world studies.","s":0},{"q":"Quelle est la différence entre PREM et PROM ?","o":["PREM : expérience des soins ; PROM : résultats de santé","PREM : rempli par le clinicien ; PROM : par le patient lui-même","PREM : générique ; PROM : spécifique d'une maladie","Aucune différence : ce sont deux synonymes"],"r":0,"e":"Les PREM (Patient-Reported Experience Measures) évaluent la satisfaction et la qualité de l'expérience ; les PROM (Patient-Reported Outcome Measures) évaluent les résultats sur la santé, comme le SF-36 ou l'EuroQol EQ-5D.","s":0},{"q":"Lequel de ces instruments est cité comme exemple de PROM ?","o":["Le questionnaire SF-36","Le questionnaire HCAHPS, d'expérience","La grille AGREE II","La checklist CONSORT 2010"],"r":0,"e":"Le SF-36 et l'EuroQol EQ-5D sont des exemples de PROM. L'HCAHPS mesure l'expérience des soins : c'est un PREM.","s":0},{"q":"Quelle stratégie de question la scoping review sur les priorités de recherche illustre-t-elle ?","o":["PICOT","PCC","PECOT","POT"],"r":1,"e":"Les scoping reviews utilisent la stratégie PCC : Population, Concept, Contexte.","s":0},{"q":"Quelle priorité arrive en tête des consensus de recherche en kinésithérapie au Portugal ?","o":["Le coût-efficacité","La qualité","Le développement professionnel","La prestation de services"],"r":0,"e":"Les priorités les plus consensuelles sont, dans l'ordre présenté : coût-efficacité, prestation de services et éducation, développement professionnel, qualité.","s":0},{"q":"Pourquoi l'adhésion au traitement est-elle un enjeu de PBE ?","o":["Elle conditionne le passage de l'essai à la pratique","Elle mesure la validité interne d'un essai clinique","Elle permet la randomisation des patients inclus","Elle remplace le consentement éclairé"],"r":0,"e":"L'adhésion est le pont entre l'efficacité démontrée en essai et le résultat obtenu en pratique : c'est un déterminant majeur de l'effectivité. C'est ce qui fait l'effectivité.","s":0},{"q":"À quelle catégorie de résultats se rattachent les effets de l'exercice sur l'anxiété et la dépression ?","o":["Aux résultats cliniques","Aux résultats humanistiques","Aux résultats économiques","Aux résultats méthodologiques"],"r":1,"e":"Qualité de vie et symptômes anxio-dépressifs relèvent des résultats humanistiques, qui donnent la perspective des patients.","s":0},{"q":"Quels outils servent à évaluer la qualité et le risque de biais d'une revue systématique ?","o":["AMSTAR et CASP","CONSORT et STROBE","COSMIN et Beaton","Rayyan et JANE"],"r":0,"e":"AMSTAR et la CASP Checklist for Systematic Review servent à évaluer la qualité et le risque de biais des revues systématiques.","s":0},{"q":"À quoi sert l'outil Rayyan ?","o":["À gérer la sélection des études d'une revue","À calculer une méta-analyse, en ligne","À enregistrer le protocole d'une revue","À choisir la revue de publication"],"r":0,"e":"Rayyan est un outil d'aide à la sélection des études dans le processus de revue.","s":0},{"q":"À quoi sert l'outil JANE ?","o":["À détecter les essais problématiques d'une revue","À trouver la revue où soumettre un article","À évaluer la qualité d'une guideline","À adapter une échelle à une autre langue"],"r":1,"e":"JANE fournit, avec le titre et les mots-clés, les meilleures revues auxquelles soumettre une publication. Il s'appuie sur le titre et les mots-clés.","s":0},{"q":"À quoi sert INSPECT-SR ?","o":["À repérer les essais problématiques des revues","À calculer la taille d'échantillon d'un essai","À évaluer les propriétés psychométriques d'un outil","À rapporter une étude observationnelle"],"r":0,"e":"INSPECT-SR (INveStigating ProblEmatic Clinical Trials in Systematic Reviews) détecte les essais problématiques qui distordent l'évidence. Ces essais distordent l'évidence des revues systématiques.","s":0},{"q":"La checklist CONSORT impose notamment de rapporter :","o":["Le flux des participants, l'allocation et l'aveuglement","Le contrôle des facteurs de confusion, en cohorte","La perspective du patient, en fin de cas","Les mesures de processus, en amélioration de la qualité"],"r":0,"e":"Elle s'applique aux essais contrôlés randomisés et exige aussi le rapport des outcomes primaires et secondaires ainsi que des analyses. Il faut rapporter la génération de la séquence et l'allocation concealment.","s":0},{"q":"La checklist STROBE impose de rapporter notamment :","o":["L'aveuglement des évaluateurs, en essai","Le design, les variables et les facteurs de confusion","Le diagramme de flux de sélection des études incluses","La rigueur d'élaboration, pour une recommandation"],"r":1,"e":"Elle couvre les études observationnelles : cohortes, cas-témoins et transversales. La taille d'échantillon doit également y figurer. Le cadre, les participants et les sources de données en font aussi partie.","s":0},{"q":"TREND vient combler l'angle mort de CONSORT pour :","o":["Les revues systématiques, avec méta-analyse","Les interventions non randomisées, comportementales","Les cas cliniques isolés, avec la perspective du patient","Les guidelines de pratique clinique"],"r":1,"e":"Sans randomisation, les garanties de CONSORT ne s'appliquent pas, mais l'intervention délibérée exige tout de même un cadre de rapport rigoureux. Il s'agit des études d'intervention non randomisées, notamment comportementales.","s":0},{"q":"La checklist CARE demande de structurer un cas clinique en incluant :","o":["Patient, chronologie, examens, interventions, résultats","La stratégie de recherche documentaire, avec les mots-clés","L'évaluation du risque de biais des essais","Les mesures de processus et d'amélioration"],"r":0,"e":"Le rapport de cas correspond à un niveau d'évidence bas : type V dans la classification Cochrane, niveau 3 dans celle de JAMA. La perspective du patient et le consentement y figurent aussi.","s":0},{"q":"SQUIRE 2.0 s'applique aux études :","o":["Randomisées, en double aveugle","D'amélioration de la qualité des soins","Observationnelles, en cohorte ou cas-témoins","De validation d'instruments de mesure"],"r":1,"e":"Elle impose de rapporter le contexte, l'intervention d'amélioration, et les mesures de processus comme de résultat.","s":0},{"q":"L'outil AGREE évalue la qualité méthodologique d'une guideline sur des domaines incluant :","o":["Le champ, la rigueur, la clarté et l'indépendance","La taille de l'échantillon, calculée à l'avance","Le risque de biais des essais inclus, un par un","La validité transculturelle, d'un pays à l'autre"],"r":0,"e":"L'indépendance éditoriale est un domaine décisif : une recommandation rédigée sans déclaration de conflits d'intérêts perd en crédibilité. La participation des parties prenantes et l'applicabilité en font aussi partie.","s":0},{"q":"Le réflexe recommandé avant de lire un article est :","o":["De lire d'abord la conclusion, puis le résumé","D'identifier le design et d'ouvrir la bonne checklist","De vérifier le facteur d'impact de la revue","De consulter le nombre de citations, sur une base de données"],"r":1,"e":"Le cours le formule ainsi : ce qui manque est souvent plus informatif que ce qui est écrit. On vérifie ensuite ce que l'article ne rapporte pas.","s":0},{"q":"Dans la méthode de Beaton, la rétrotraduction doit être réalisée par des traducteurs :","o":["Spécialistes du domaine de la santé, et bilingues","Aveugles à l'original et extérieurs à la santé","Membres du comité d'experts, ensemble","Auteurs de l'instrument d'origine"],"r":1,"e":"Cette double condition évite qu'ils reconstituent l'original de mémoire ou par connaissance du jargon, ce qui masquerait les écarts de sens.","s":0},{"q":"La méthodologie de la scoping review comporte :","o":["3 étapes","5 étapes","6 étapes","9 étapes"],"r":1,"e":"Identifier la question, définir la stratégie de recherche, sélectionner les études, cartographier l'information, décrire sommairement les résultats.","s":0},{"q":"Le F de la grille FAITH pose la question :","o":["Ont-ils trouvé la majorité des études ?","Les ont-ils évaluées individuellement ?","Que veulent dire les résultats ?","Sont-ils hétérogènes ?"],"r":0,"e":"A pour l'évaluation individuelle via RAMBOMAN, I pour l'inclusion des seules études de haute qualité, T pour le sens des résultats, H pour l'hétérogénéité.","s":0},{"q":"Le H de la grille FAITH interroge :","o":["L'exhaustivité de la recherche","L'hétérogénéité des résultats","L'honnêteté des auteurs","L'applicabilité clinique"],"r":1,"e":"Une hétérogénéité forte interdit souvent de combiner les études : le résultat global perdrait toute signification clinique.","s":0},{"q":"La nouvelle pyramide de l'évidence modifie le modèle classique en posant que :","o":["Les revues systématiques disparaissent de la pyramide","Les revues deviennent la lentille des études primaires","Les essais randomisés passent au sommet de la pyramide","Les opinions d'experts remontent vers le haut de la pyramide"],"r":1,"e":"Conséquence pratique : un essai randomisé mal conduit peut valoir moins qu'une cohorte rigoureuse. La qualité de réalisation compte autant que le design. Les frontières entre étages deviennent ondulées.","s":0},{"q":"Les données de vie réelle répondent principalement à la question :","o":["De l'efficacité","De l'effectivité","Du coût","De la sécurité"],"r":1,"e":"Les essais contrôlés randomisés, à validité interne élevée, répondent à l'efficacité. La formule du cours : l'efficacité ne se traduit pas toujours en effectivité.","s":0},{"q":"Parmi les priorités de recherche les plus consensuelles identifiées chez les kinésithérapeutes portugais et les patients figure :","o":["Le coût-efficacité","La biomécanique","L'imagerie","La pharmacologie"],"r":0,"e":"S'y ajoutent la prestation de services et l'éducation, le développement professionnel et la qualité. L'étude illustre l'usage de la stratégie PCC.","s":0},{"q":"L'adhésion au traitement est présentée comme :","o":["Un facteur secondaire, peu déterminant","Le pont entre l'essai et le résultat obtenu en cabinet","Un problème purement éducatif, réglé par l'information","Un indicateur économique, de coût"],"r":1,"e":"C'est un déterminant majeur de l'effectivité, à relier aux résultats humanistiques et au contexte social de la définition de l'APTA.","s":0},{"q":"L'outil JANE sert à :","o":["Enregistrer une revue systématique","Trouver la revue où soumettre un article","Évaluer le risque de biais des essais inclus","Gérer la sélection des études"],"r":1,"e":"PROSPERO enregistre les titres de revues systématiques, Rayyan gère la sélection, AMSTAR et CASP évaluent la qualité. JANE part du titre et des mots-clés.","s":0},{"q":"INSPECT-SR a pour fonction :","o":["De détecter les essais problématiques","De rédiger les protocoles d'essai","D'analyser les données brutes","De traduire les échelles de mesure"],"r":0,"e":"Des essais fabriqués ou gravement défaillants intégrés à une méta-analyse peuvent en inverser la conclusion : les repérer est devenu un enjeu méthodologique. Ces essais distordent l'évidence.","s":0},{"q":"G-I-N et NICE sont des ressources permettant de trouver :","o":["Des revues systématiques, de référence","Des bases de données de guidelines","Des instruments de mesure, validés","Des essais cliniques en cours de recrutement"],"r":1,"e":"COMET et ICHOM concernent les Core Outcome Sets et les mesures centrées patient ; Cochrane les revues systématiques de référence.","s":0},{"q":"Le tableau de correspondance à connaître associe « instrument de mesure » à :","o":["PRISMA","COSMIN","Beaton","AGREE"],"r":1,"e":"Et « traduction d'échelle » à Beaton. Le tableau complet couvre neuf correspondances, du design à la checklist qui lui convient.","s":0},{"q":"L'étude sur les effets physiologiques de l'exercice sur l'anxiété et la dépression illustre :","o":["Un outcome clinique, mesuré par le praticien","Un outcome humanistique, auto-rapporté","Un outcome économique, en coûts","Une étude méthodologique, de validation"],"r":1,"e":"Elle converge avec le traitement non médicamenteux des troubles anxieux et du stress abordé en Physiopathologie II. Il est mesuré par des PROM.","s":0},{"q":"Comment le cours définit-il la science ?","o":["Un ensemble d'opinions partagées par les experts","Des connaissances sur les lois objectives des phénomènes","Une accumulation de données, sans aucune interprétation","Une croyance validée par la tradition, au fil des générations"],"r":1,"e":"La science est l'ensemble des connaissances humaines à propos de la nature, de la société et de la pensée, acquises par la découverte et l'explication des lois objectives qui régissent les phénomènes. Ces lois sont découvertes et expliquées.","s":1},{"q":"Quel est le point de départ de la démarche scientifique selon le cours ?","o":["Le besoin de résoudre les problèmes du quotidien","La volonté de publier dans des revues prestigieuses","Le financement de la recherche, public ou privé","La curiosité propre aux universités"],"r":0,"e":"Le cours part du besoin des personnes de résoudre les problèmes du quotidien.","s":1},{"q":"Qu'est-ce que la méthode scientifique ?","o":["Une liste de publications de référence","Un système de règles et de processus de recherche","Une technique statistique particulière","Un protocole de soin standardisé, validé par les experts"],"r":1,"e":"La méthode scientifique consiste en un système de règles et de processus sur lequel se fonde la recherche.","s":1},{"q":"Quels sont les quatre caractères de la méthode scientifique ?","o":["Systématique, contrôlé, empirique et critique","Rapide, économique, reproductible et publiable","Qualitatif, quantitatif, mixte et narratif","Descriptif, analytique, prédictif et prescriptif"],"r":0,"e":"La méthode scientifique est systématique, contrôlée, empirique et critique ; c'est la forme la plus rigoureuse d'acquisition de nouvelles connaissances.","s":1},{"q":"Que signifie le caractère « systématique » de la méthode scientifique ?","o":["Elle utilise toujours les mêmes tests statistiques","Elle suit une séquence logique, avec ordre et discipline","Elle est toujours publiée, quels que soient les résultats","Elle s'applique à tous les domaines du savoir"],"r":1,"e":"Le caractère systématique implique une séquence logique d'étapes, avec ordre et discipline pour assurer la fiabilité. Cela assure sa fiabilité.","s":1},{"q":"Que signifie le caractère « contrôlé » de la méthode scientifique ?","o":["Un comité de surveillance contrôle le chercheur, à chaque étape","On contrôle les facteurs externes, non liés aux variables","Les données sont vérifiées deux fois, par deux personnes","L'étude est financée par des fonds publics"],"r":1,"e":"Le caractère contrôlé signifie qu'on contrôle l'impact des facteurs externes et des influences qui ne sont pas liés aux variables analysées. On contrôle aussi les influences sans lien avec les variables analysées.","s":1},{"q":"Que signifie le caractère « empirique » ?","o":["Les conclusions viennent de l'observation directe du réel","La recherche repose sur l'expérience personnelle du chercheur","Les résultats restent approximatifs, sans précision","La méthode reste purement théorique, sans mesure"],"r":0,"e":"Le caractère empirique signifie que les conclusions tirées résultent de l'observation directe, fondées sur la réalité et l'évidence observée.","s":1},{"q":"Que signifie le caractère « critique » de la méthode scientifique ?","o":["Le chercheur doit critiquer les travaux antérieurs","Les résultats sont soumis aux pairs, qui les corrigent","La recherche porte sur des situations critiques, en urgence","Les limites de l'étude doivent être signalées"],"r":1,"e":"Le caractère critique impose que le chercheur soumette ses résultats aux autres chercheurs : l'information doit être validée et corrigée. L'information doit être validée et corrigée.","s":1},{"q":"Quelle est la première étape du processus de recherche ?","o":["Le choix de la méthode statistique","La formulation de la question","La sélection de l'échantillon","La demande de financement"],"r":1,"e":"La question est la première étape et est essentielle pour définir le processus de la recherche, c'est-à-dire le parcours que nous allons faire.","s":1},{"q":"À quel type de question correspond « Que faire dans cette situation ou ce problème ? »","o":["Diagnostic du problème","Intervention ou traitement","Pronostic ou évolution","Fréquence ou prévalence du problème"],"r":1,"e":"« Que faire dans cette situation ou ce problème ? » correspond à une question d'intervention ou de traitement.","s":1},{"q":"À quel type de question correspond « Quelle est la cause de la survenue du problème ? »","o":["Étiologie / risque","Pronostic","Diagnostic","Expériences des patients"],"r":0,"e":"Cette formulation correspond à une question d'étiologie ou de risque, c'est-à-dire de cause de la maladie.","s":1},{"q":"À quel type de question correspond « Ce patient a-t-il le problème ou cette situation ? »","o":["Fréquence","Diagnostic","Intervention","Étiologie"],"r":1,"e":"« Ce patient a-t-il le problème ou cette situation ? » est une question de diagnostic.","s":1},{"q":"À quel type de question correspond « Cette situation ou ce problème est-il fréquent ? »","o":["Pronostic ou évolution","Fréquence du problème posé","Diagnostic du problème","Étiologie ou cause"],"r":1,"e":"Cette formulation correspond à une question de fréquence du problème.","s":1},{"q":"À quel type de question correspond « Que pense le patient de sa situation ou de son problème ? »","o":["Expériences des patients","Pronostic ou évolution","Intervention ou traitement","Diagnostic ou dépistage du problème"],"r":0,"e":"Cette question relève des expériences des patients, domaine des études qualitatives.","s":1},{"q":"Quel type de question est « L'aspirine est-elle efficace dans le rhume ? »","o":["Diagnostic","Intervention","Fréquence","Étiologie"],"r":1,"e":"C'est une question d'intervention, puisqu'elle porte sur l'efficacité d'un traitement.","s":1},{"q":"Quel type de question est « La malaria est-elle fréquente en Indonésie ? »","o":["Fréquence","Pronostic","Étiologie","Diagnostic"],"r":0,"e":"C'est une question de fréquence du problème.","s":1},{"q":"Quel type de question est « Fumer provoque-t-il le cancer du poumon ? »","o":["Intervention","Étiologie ou risque","Diagnostic","Expériences des patients"],"r":1,"e":"C'est une question d'étiologie ou de risque, c'est-à-dire de cause du problème.","s":1},{"q":"Quel type de question est « Le test COVID est-il fiable pour les asymptomatiques ? »","o":["Diagnostic","Pronostic","Intervention","Fréquence"],"r":0,"e":"C'est une question de diagnostic, puisqu'elle porte sur la fiabilité d'un test.","s":1},{"q":"Quel type de question est « Quelles sont les maladies les plus probables comme conséquence de l'usage excessif du téléphone portable ? »","o":["Diagnostic du problème, par un test","Pronostic ou évolution de la maladie","Intervention ou traitement","Fréquence ou prévalence"],"r":1,"e":"C'est une question de pronostic, c'est-à-dire d'évolution de la maladie et de probabilité de survenue.","s":1},{"q":"Quels sont les deux grands paradigmes de recherche ?","o":["Descriptif et analytique","Quantitatif et qualitatif","Primaire et secondaire","Interne et externe"],"r":1,"e":"Le cours distingue le paradigme quantitatif et le paradigme qualitatif ; souvent ils se complètent.","s":1},{"q":"Quelle est la relation entre les paradigmes quantitatif et qualitatif ?","o":["Ils s'excluent mutuellement","Souvent ils se complètent","Le qualitatif est toujours supérieur","Le quantitatif remplace le qualitatif"],"r":1,"e":"Le cours indique que souvent les deux paradigmes se complètent.","s":1},{"q":"Sur quoi repose le choix entre les différents types de recherche ?","o":["Sur l'objet et l'objectif de la recherche","Sur le budget disponible, au départ","Sur les préférences personnelles du chercheur","Sur la revue visée pour la publication"],"r":0,"e":"Chaque méthode comporte un certain nombre de types de recherche et le choix se fait en fonction de l'objet et de l'objectif de la recherche.","s":1},{"q":"Quelle unité précède PBE I dans le cursus ?","o":["PBE II, en troisième année","MTP, en première année","Projet I, en quatrième année","Aucune, PBE I ouvre le cursus"],"r":1,"e":"Le cursus enchaîne MTP (1re année), PBE I (2e année), PBE II (3e année) puis Projet I et II (4e année).","s":1},{"q":"Quelle thématique traite de la validité interne, de la validité externe et des biais ?","o":["Thématique 1 · Évaluation et résultats","Thématique 2 · Design et types d'études","Thématique 3 · Méthodes et instruments","Thématique 4 · Partage et diffusion"],"r":1,"e":"La thématique 2 porte sur le design et les types d'études : validité interne, validité externe, biais, études primaires, secondaires et méthodologiques.","s":1},{"q":"Quelle thématique traite des propriétés psychométriques ?","o":["Thématique 1","Thématique 2","Thématique 3","Thématique 4"],"r":2,"e":"La thématique 3 porte sur les méthodes et instruments : types de résultats et propriétés psychométriques.","s":1},{"q":"Dans quelle thématique figure la pyramide de l'évidence ?","o":["Thématique 4","Thématique 1","Thématique 2","Thématique 3"],"r":0,"e":"La thématique 4 traite du partage et de la diffusion des résultats : pyramide de l'évidence, pratique fondée sur l'évidence et pratique informée par l'évidence. La thématique 4 porte sur le partage et la diffusion des résultats.","s":1},{"q":"Quelles études sont classées comme secondaires dans le programme ?","o":["Les études observationnelles et expérimentales","Les revues, méta-analyses et guidelines","Les adaptations culturelles d'instruments","Les études de cas cliniques, isolées"],"r":1,"e":"Les études secondaires regroupent les scoping reviews, les revues systématiques, les méta-analyses et les guidelines. Les revues comprennent les scoping reviews et les revues systématiques.","s":1},{"q":"À quoi correspondent les études méthodologiques dans le programme ?","o":["Aux essais cliniques randomisés et contrôlés","À l'adaptation et à la validation d'outils","Aux enquêtes de prévalence, en population","Aux revues de la littérature, narratives"],"r":1,"e":"Les études méthodologiques concernent l'adaptation culturelle et la validation d'instruments. L'adaptation est culturelle ; les outils sont des instruments de mesure.","s":1},{"q":"Quelle note minimale faut-il obtenir à chaque moment d'évaluation pour être dispensé de l'examen final ?","o":["8,5","10","12","15"],"r":0,"e":"L'étudiant doit démontrer à chaque moment des connaissances équivalentes ou supérieures à une note correspondant à 8,5, et obtenir une moyenne finale égale ou supérieure à 10 points.","s":1},{"q":"Que se passe-t-il si l'étudiant a moins de 10 points en contrôle continu ?","o":["Il redouble automatiquement toute l'année","Il passe un examen final sur toute la matière","Il repasse uniquement le moment échoué","Il est dispensé de tout examen final"],"r":1,"e":"En dessous de 10 points en contrôle continu, l'étudiant doit passer un examen final écrit incluant toute la matière enseignée, avec une pondération de 100 %. L'examen est écrit, avec une pondération de 100 %.","s":1},{"q":"Le caractère « systématique » de la méthode scientifique implique :","o":["Une séquence logique, avec ordre et discipline","Le contrôle des facteurs externes","Le recours à l'observation directe","La soumission des résultats aux pairs, pour validation"],"r":0,"e":"Les trois autres caractères sont : contrôlé, empirique et critique. Chacun répond à une menace différente sur la qualité de la connaissance produite. Ordre et discipline assurent la fiabilité.","s":1},{"q":"Le caractère « critique » de la méthode scientifique signifie que les résultats :","o":["Sont définitifs, une fois publiés","Sont soumis aux pairs, validés et corrigés","Doivent être négatifs, pour être crédibles","Restent confidentiels, jusqu'à la fin de l'étude"],"r":1,"e":"C'est ce qui distingue la science d'une conviction personnelle : elle s'expose délibérément à la contestation par ses pairs.","s":1},{"q":"Le caractère « empirique » implique que les conclusions :","o":["Découlent d'un raisonnement théorique, sans données","Sont issues de l'observation directe de la réalité","Proviennent d'un consensus d'experts","Reposent sur des modèles mathématiques"],"r":1,"e":"Le caractère contrôlé s'y ajoute : on maîtrise l'impact des facteurs externes non liés aux variables analysées. Elles se fondent sur l'évidence observée.","s":1},{"q":"La science naît, selon le cours :","o":["Du hasard des découvertes","Du besoin de résoudre les problèmes du quotidien","De la curiosité pure, sans aucune application pratique","Des institutions universitaires"],"r":1,"e":"Elle se définit comme l'ensemble des connaissances humaines sur la nature, la société et la pensée, acquises par la découverte des lois objectives qui régissent les phénomènes.","s":1},{"q":"La méthode scientifique est décrite comme :","o":["Une hypothèse de travail, provisoire et révisable","Un système de règles et de processus","Une opinion argumentée, publiée","Un protocole administratif, obligatoire"],"r":1,"e":"Cette rigueur ne garantit pas la vérité de chaque résultat, mais elle rend possibles la vérification et la correction. C'est la forme la plus rigoureuse d'acquisition de connaissances nouvelles.","s":1},{"q":"La question « Ce patient a-t-il le problème ou cette condition ? » relève d'une question :","o":["D'intervention","D'étiologie","De diagnostic","De fréquence"],"r":2,"e":"Les six types : intervention ou traitement, étiologie ou risque, pronostic, diagnostic, fréquence, et expériences des patients.","s":1},{"q":"La question « Que pense le patient de sa situation ? » relève :","o":["Du pronostic, de l'évolution","Des expériences des patients","Du diagnostic, du dépistage","De l'intervention, du traitement proposé"],"r":1,"e":"Ce type de question appelle typiquement un paradigme qualitatif, là où les questions d'intervention appellent un paradigme quantitatif.","s":1},{"q":"La question « La malaria est-elle fréquente en Indonésie ? » est une question :","o":["De fréquence","D'étiologie","De pronostic","De diagnostic"],"r":0,"e":"Elle appelle une étude transversale, selon la correspondance entre type de question et design vue au cours 4.","s":1},{"q":"Les deux grands paradigmes de recherche sont :","o":["Quantitatif et qualitatif","Expérimental et observationnel","Primaire et secondaire","Descriptif et analytique"],"r":0,"e":"Le cours précise qu'ils se complètent souvent et que chacun comporte plusieurs types de recherche.","s":1},{"q":"Le choix entre les différents types de recherche se fait en fonction :","o":["Des moyens disponibles, au départ","De l'objet et de l'objectif de l'étude","De la mode scientifique du moment","Du temps imparti pour l'étude"],"r":1,"e":"C'est la question qui commande la méthode, et non l'inverse — principe qui traverse tout le module.","s":1},{"q":"Dans le cursus , l'unité qui précède PBE I est :","o":["Projet I, en quatrième année","MTP, en première année","PBE II, en troisième année","Projet II, en quatrième et dernière année"],"r":1,"e":"La progression complète : MTP en première année, PBE I en deuxième, PBE II en troisième, Projet I et II en quatrième.","s":1},{"q":"La thématique du programme traitant des propriétés psychométriques est :","o":["Évaluation et résultats en santé","Design et types d'études","Méthodes et instruments","Partage et diffusion des résultats"],"r":2,"e":"La pyramide de l'évidence et la PBE relèvent de la quatrième thématique ; validité, biais et types d'études de la deuxième.","s":1},{"q":"Parmi les quatre phases du processus de recherche, la phase méthodologique répond à la question :","o":["Que cherche-t-on à savoir ?","Comment allons-nous faire le voyage ?","Qu'avons-nous trouvé, au terme du recueil ?","À qui le dire, et comment ?"],"r":1,"e":"Elle couvre le design, la population, les variables, les procédures et l'analyse. La phase conceptuelle pose la question, l'empirique recueille, la quatrième diffuse.","s":1},{"q":"Le E de l'acronyme FINER signifie :","o":["Efficace","Éthique","Évaluable","Économique"],"r":1,"e":"F pour faisable, I pour intéressante, N pour nouveauté, E pour éthique, R pour relevant, c'est-à-dire pertinente pour la connaissance et la communauté.","s":1},{"q":"Le I de FINER porte sur le caractère :","o":["Innovant, jamais étudié","Intéressant pour les pairs","Indépendant, sans conflit","Interdisciplinaire, à plusieurs équipes"],"r":1,"e":"La nouveauté est couverte par le N, qui pose la question de ce que l'étude ajoute à la connaissance existante. L'intérêt concerne la communauté et les pairs.","s":1},{"q":"La déclinaison PICOT ajoute à PICO :","o":["Le design de l'étude, pour les revues systématiques","Le temps, pour les études expérimentales","Le contexte, pour les études qualitatives","Le concept, pour les scoping reviews"],"r":1,"e":"PICOS ajoute le design, PECOT substitue l'exposition à l'intervention pour les études non expérimentales, PCC vaut pour les scoping reviews.","s":1},{"q":"La déclinaison PICo, avec un o minuscule, s'applique :","o":["Aux études qualitatives, avec l'Intérêt et le Contexte","Aux revues systématiques, avec méta-analyse","Aux études de prévalence et d'incidence","Aux essais randomisés, avec un groupe contrôle et un suivi"],"r":0,"e":"POT sert aux études de prévalence et d'incidence. Chaque déclinaison adapte la structure de la question au type d'étude envisagé.","s":1},{"q":"L'évaluation de l'unité PBE I repose sur :","o":["Un examen final unique, écrit","Deux fiches écrites individuelles, à moyenne pondérée","Un travail de groupe, présenté à l'oral","Un contrôle continu hebdomadaire, sur l'ensemble de l'année"],"r":1,"e":"Pour être dispensé de l'examen final, il faut au moins 8,5 à chaque moment et une moyenne finale d'au moins 10. Ces deux fiches sont obligatoires.","s":1},{"q":"En dessous de 10 en contrôle continu, l'étudiant :","o":["Repasse uniquement le moment manqué","Passe un examen final sur toute la matière","Redouble l'unité, sans examen de rattrapage possible","Conserve sa meilleure note"],"r":1,"e":"La pondération de 100 % signifie que le contrôle continu ne compte plus du tout : l'examen final se substitue intégralement. L'examen est écrit et pondéré à 100 %.","s":1},{"q":"La question de recherche est qualifiée d'étape essentielle parce que :","o":["Elle est la plus rapide à formuler","Elle définit le parcours de la recherche","Elle détermine le financement","Elle fixe la durée de l'étude, du début à la fin"],"r":1,"e":"Le cours file la métaphore : la question définit la destination du voyage, la phase méthodologique l'itinéraire pour s'y rendre.","s":1},{"q":"Quelles sont les quatre phases du processus de recherche ?","o":["Conceptuelle, méthodologique, empirique, diffusion","Hypothèse, expérience, résultat, publication","Question, échantillon, analyse, conclusion","Théorique, pratique, statistique, éthique"],"r":0,"e":"Les quatre phases sont : 1) conceptuelle, 2) méthodologique, 3) empirique, 4) diffusion/partage des résultats.","s":2},{"q":"Que dit le cours sur l'indépendance des phases du processus ?","o":["Elles sont totalement indépendantes","Elles ne sont pas totalement indépendantes","Elles doivent être menées en même temps","Leur ordre est indifférent, d'un projet à l'autre"],"r":1,"e":"Le cours précise que les phases du processus ne sont pas totalement indépendantes les unes des autres.","s":2},{"q":"Que faut-il vérifier avant de commencer un projet de recherche ?","o":["Qu'elle est nouvelle, pertinente et intéressante","Que le financement est acquis, pour toute sa durée","Que la revue de publication est choisie","Que l'échantillon est déjà recruté"],"r":0,"e":"Après avoir eu l'idée et avant de commencer, il faut s'assurer que l'étude n'existe pas encore, qu'elle est pertinente pour la kinésithérapie et qu'elle est intéressante. La pertinence s'apprécie pour la kinésithérapie ; elle ne doit pas déjà exister.","s":2},{"q":"Que fait une revue de la littérature selon le cours ?","o":["Elle liste les publications, sans les juger","Elle analyse l'existant de façon critique, débats compris","Elle remplace la collecte de données","Elle sert seulement à trouver des références bibliographiques"],"r":1,"e":"La revue de la littérature est une approche critique de la littérature existante : elle présente résultats et conclusions, identifie débats et divergences, aborde problématiques et outcomes et suggère la méthode à utiliser. Elle présente les résultats antérieurs, identifie les débats et suggère la méthode.","s":2},{"q":"Que signifie le F de FINER ?","o":["Fiable, reproductible d'un centre et d'un jour à l'autre","Faisable en participants, méthodes, temps et coûts","Fondamental, pour la science et la théorie","Financé, par une institution publique"],"r":1,"e":"F correspond à Feasible : la faisabilité de la question en termes de participants, méthodes, temps, coûts, etc.","s":2},{"q":"Que signifie le N de FINER ?","o":["Nécessaire, pour les patients","Nouveau, ajoutant à la connaissance","Normalisé, selon une procédure standard","National, mené dans tout le pays"],"r":1,"e":"N correspond à Novel : qu'est-ce que cela ajoute à la connaissance ?","s":2},{"q":"Que signifie le R de FINER ?","o":["Reproductible, d'une équipe à l'autre","Randomisé, en double aveugle","Relevant, pertinent pour la communauté","Rigoureux, sur le plan statistique"],"r":2,"e":"R correspond à Relevant : les implications sont-elles pertinentes pour la connaissance et la communauté ? La pertinence s'apprécie pour la connaissance et la communauté.","s":2},{"q":"Que signifie l'acronyme PICO ?","o":["Population, Intervention, Comparaison, Outcome","Problème, Interprétation, Contexte, Objectif","Patient, Instrument, Critère, Observation","Protocole, Inclusion, Contrôle, Objectif"],"r":0,"e":"PICO = Population/Problème, Intervention/Exposition, Comparaison/Contrôle, Outcome (mesure de résultat).","s":2},{"q":"Comment le cours décrit-il le rôle de PICO ?","o":["Une étape facultative, en fin de rédaction","L'étape primordiale, la destination du voyage","Une méthode d'analyse statistique","Un outil de sélection de la revue"],"r":1,"e":"PICO est une étape primordiale pour tout le processus de recherche : elle définit la « destination du voyage ».","s":2},{"q":"Que représente le O de PICO ?","o":["L'objectif de l'étude, principal","L'outcome, la variable dépendante mesurée","L'observation clinique, faite au cours de l'examen","L'organisation de l'étude, en centres"],"r":1,"e":"Le O désigne l'outcome : les résultats pertinents à observer, c'est-à-dire les variables dépendantes mesurées (douleur, fonctionnalité, qualité de vie, force, amplitude…). Exemples : douleur, fonctionnalité, qualité de vie, force, amplitude.","s":2},{"q":"Quelle déclinaison de PICO s'applique aux scoping reviews ?","o":["PICOT","PECOT","PCC","POT"],"r":2,"e":"PCC — Population, Concept, Contexte — s'applique aux scoping reviews. PCC : Population, Concept, Contexte.","s":2},{"q":"Quelle déclinaison s'applique aux études qualitatives ?","o":["PICo","PICOS","POT","PECOT"],"r":0,"e":"PICo — Population/Patient/Problème, Intérêt, Contexte — s'applique aux études qualitatives. PICo : Population, Intérêt, Contexte.","s":2},{"q":"Quelle déclinaison s'applique aux études non expérimentales ?","o":["PICOT","PECOT","PCC","PICo"],"r":1,"e":"PECOT — Population, Exposition, Outcomes, Temps — s'applique aux études non expérimentales ; PICOT concerne les études expérimentales.","s":2},{"q":"Quelle déclinaison s'applique aux études de prévalence et d'incidence ?","o":["POT","PICOS","PCC","PICo"],"r":0,"e":"POT — Population, Outcomes, Temps — s'applique aux études de prévalence et d'incidence. POT : Population, Outcomes, Temps.","s":2},{"q":"Combien d'objectifs le cours recommande-t-il ?","o":["Un seul objectif, au total","Un général et jusqu'à trois spécifiques","Au moins cinq objectifs spécifiques","Autant que de variables mesurées, dans l'étude"],"r":1,"e":"Les objectifs doivent comprendre 1 objectif général ou primaire et jusqu'à environ 3 spécifiques ou secondaires.","s":2},{"q":"Quels verbes le cours recommande-t-il pour formuler les objectifs ?","o":["« Penser », « supposer »","« Déterminer », « évaluer »","« Prouver », « démontrer »","« Croire », « estimer »"],"r":1,"e":"Le cours recommande des verbes comme « déterminer » et « évaluer ».","s":2},{"q":"Comment le cours définit-il une population ?","o":["Un sous-ensemble de sujets, tirés au sort","Tous les éléments qui partagent les critères","Les patients d'un service donné, sur une période définie","Les sujets ayant accepté de participer"],"r":1,"e":"La population est le nombre total d'éléments qui possèdent des caractéristiques communes pertinentes (critères d'éligibilité) pour l'étude. Ces caractéristiques communes sont les critères d'éligibilité.","s":2},{"q":"Quelle qualité l'échantillon doit-il posséder ?","o":["Être le plus grand possible","Être représentatif de la population","Être homogène en âge, seulement","Être recruté dans un seul centre, pour l'homogénéité"],"r":1,"e":"L'échantillon est un sous-ensemble de la population ; il doit être représentatif, ses caractéristiques devant se rapprocher le plus possible de celles de la population.","s":2},{"q":"Quelle conséquence a une grande homogénéité de l'échantillon ?","o":["Plus de validité interne, moins de généralisation","Plus de validité interne et de généralisation","Moins de validité interne, plus de généralisation","Aucun effet, ni sur l'une ni sur l'autre"],"r":0,"e":"Plus il y a d'homogénéité, plus grande est la validité interne, mais plus faible est le potentiel de généralisation des résultats.","s":2},{"q":"Quelle est la meilleure technique d'échantillonnage selon le cours ?","o":["L'échantillonnage de convenance","L'échantillonnage intentionnel","L'échantillonnage aléatoire randomisé","L'échantillonnage par quotas"],"r":2,"e":"Parmi les échantillons aléatoires, la randomisation est présentée comme la meilleure technique d'échantillonnage.","s":2},{"q":"Quel effet a la réduction de la marge d'erreur souhaitée ?","o":["L'échantillon devra être plus grand","L'échantillon pourra être plus petit","Cela n'a aucun effet sur la taille","Cela augmente le degré de confiance"],"r":0,"e":"Plus la marge d'erreur maximale souhaitée est petite, plus l'échantillon devra être grand.","s":2},{"q":"Que se passe-t-il quand le degré de confiance augmente ?","o":["L'intervalle des résultats devient plus étroit","L'intervalle des résultats possibles s'élargit","La marge d'erreur disparaît totalement","La population étudiée change de taille"],"r":1,"e":"Plus le degré de confiance établi est élevé, plus l'intervalle de résultats possibles au sein d'un échantillon sera large ; cet intervalle se délimite en écarts-types. Cet intervalle se délimite en écarts-types.","s":2},{"q":"Comment définit-on la variable indépendante ?","o":["C'est l'effet : le résultat observé","C'est la cause : elle peut être manipulée","C'est la mesure finale : relevée en fin d'étude","C'est un biais : une variable de confusion"],"r":1,"e":"La variable indépendante peut être manipulée, elle explique le résultat (relation, cause) : c'est la variable « cause ».","s":2},{"q":"Quelles sont les trois familles de résultats en santé ?","o":["Cliniques, humanistiques et économiques","Primaires, secondaires et tertiaires","Objectifs, subjectifs et mixtes","Quantitatifs, qualitatifs et mixtes"],"r":0,"e":"Les résultats cliniques donnent la perspective des professionnels, les humanistiques celle des patients, familles et aidants, et les économiques celle du payeur et de la société.","s":2},{"q":"Quel exemple correspond à un résultat humanistique ?","o":["Le grade de force musculaire","La qualité de vie, la douleur ressentie","Le nombre de consultations, sur une année de suivi","Le coût total de l'intervention"],"r":1,"e":"Les résultats humanistiques donnent la perspective des patients : qualité de vie, intensité de la douleur.","s":2},{"q":"Quel exemple correspond à un résultat économique ?","o":["L'amplitude de mouvement, au goniomètre","Les consultations, les coûts et la productivité","La qualité de vie, auto-évaluée par le patient","Le grade de force, au testing manuel"],"r":1,"e":"Les résultats économiques comprennent le nombre de consultations, les interventions, les coûts et la productivité. Les interventions en font aussi partie.","s":2},{"q":"Que sont les Core Outcomes Sets (COS) ?","o":["Des tests statistiques standardisés","Un ensemble minimal de domaines de résultats","Des questionnaires validés, en une langue","Des critères d'inclusion obligatoires"],"r":1,"e":"Les Core Outcomes Sets constituent un ensemble minimal de domaines de résultats considérés fondamentaux. Ces domaines sont considérés comme fondamentaux.","s":2},{"q":"Que désignent les PROM et PREM ?","o":["Des mesures de performance, faites par le professionnel","Des mesures rapportées par le patient lui-même","Des dispositifs de mesure instrumentale","Des protocoles de randomisation des essais cliniques"],"r":1,"e":"PROM et PREM sont les Patient Reported Outcome and Experience Measures, mesures rapportées par les patients : qualité de vie, intensité de la douleur.","s":2},{"q":"Quelles sont les quatre étapes de la phase empirique ?","o":["Recueillir, préparer, analyser, interpréter","Formuler, tester, valider, publier","Randomiser, traiter, mesurer, comparer","Lire, écrire, présenter, publier"],"r":0,"e":"La phase empirique comprend : 1) recueillir les données, 2) préparer les données en saisissant la base, 3) analyser les données, 4) interpréter les résultats.","s":2},{"q":"Quelle limite le cours fixe-t-il pour le contenu d'une diapositive ?","o":["Pas plus de 3 lignes et de 10 mots par ligne","Pas plus de 6 lignes et de 6 mots par ligne","Pas plus de 10 lignes, sans limite de mots","Aucune limite n'est fixée, ni en lignes ni en mots"],"r":1,"e":"Les diapositives ne doivent pas contenir plus de 6 lignes de texte ni plus de 6 mots par ligne, avec environ 1 minute par diapositive ; les diapositives ne sont pas des antisèches. On compte environ une minute par diapositive.","s":2},{"q":"Les vérifications préalables à tout projet de recherche portent sur le fait que l'étude :","o":["Nouvelle, pertinente et intéressante","Finançable, rapide et publiable","Simple, courte et peu coûteuse, en un seul centre","Approuvée par le directeur de recherche"],"r":0,"e":"Ces trois questions se posent après avoir eu l'idée et avant de s'engager : elles évitent de reproduire un travail déjà fait ou sans portée. Elle ne doit pas déjà exister et doit être pertinente pour la kinésithérapie.","s":2},{"q":"La revue de la littérature, dans la phase conceptuelle :","o":["Se contente de lister les publications","Présente l'existant et ses débats, de façon critique","Remplace l'étude, en évitant toute collecte de données","Fixe la méthodologie, à elle seule"],"r":1,"e":"C'est une approche critique : elle ne recense pas, elle situe le projet dans un état des savoirs et de leurs désaccords.","s":2},{"q":"Le O de PICO correspond à :","o":["L'objectif de l'étude","L'outcome, ou résultat","L'observation clinique","L'organisation, ou plan"],"r":1,"e":"P pour population ou problème, I pour intervention ou exposition, C pour comparaison ou contrôle, O pour outcome.","s":2},{"q":"Concernant les objectifs d'une recherche, le cours recommande :","o":["Un seul objectif global","Un général et environ trois spécifiques","Au moins dix objectifs","Autant d'objectifs que de variables"],"r":1,"e":"Ils doivent identifier les variables, leur relation possible et la nature de la population, rester simples, et employer des verbes comme « déterminer » ou « évaluer ».","s":2},{"q":"Plus les critères d'éligibilité sont rigoureux :","o":["Plus l'échantillon est hétérogène","Plus de validité interne, moins de généralisation","Plus les deux validités augmentent ensemble","Moins l'étude est fiable, sur le plan statistique surtout"],"r":1,"e":"C'est l'arbitrage fondamental du design : contrôler pour conclure, ou ouvrir pour généraliser. On ne peut maximiser les deux à la fois.","s":2},{"q":"La variable indépendante se définit comme :","o":["L'effet observé, mesuré à la fin de l'étude","La cause, manipulable, du résultat","Une variable parasite, à contrôler","Une variable qui n'est pas mesurée"],"r":1,"e":"La variable dépendante est l'effet, c'est-à-dire le résultat de la variable indépendante.","s":2},{"q":"Le nombre de séances et les coûts relèvent des résultats :","o":["Cliniques","Humanistiques","Économiques","Méthodologiques"],"r":2,"e":"Ils s'apprécient dans la perspective du payeur et de la société. La productivité entre également dans cette catégorie.","s":2},{"q":"La phase empirique comporte quatre étapes :","o":["Recueillir, préparer, analyser, interpréter","Questionner, chercher, évaluer, appliquer","Concevoir, réaliser, publier et diffuser largement","Observer, mesurer, comparer, conclure"],"r":0,"e":"La préparation consiste notamment à saisir la base de données, étape souvent sous-estimée et pourtant décisive pour la qualité de l'analyse.","s":2},{"q":"Selon le cours, publier revient à :","o":["Défendre une position, face aux pairs","Ajouter une brique au mur de la connaissance","Obtenir une reconnaissance, académique","Clore un projet, définitivement"],"r":1,"e":"Les voies de diffusion citées sont la communication orale, le poster, les revues, les livres et les newsletters.","s":2},{"q":"La réduction de la marge d'erreur souhaitée a pour effet :","o":["De diminuer la taille d'échantillon nécessaire","D'augmenter la taille d'échantillon nécessaire","De n'avoir aucun effet","De réduire le niveau de confiance"],"r":1,"e":"De même, augmenter le degré de confiance exige davantage de participants : précision et certitude se paient toutes deux en effectifs.","s":2},{"q":"Une grande homogénéité de l'échantillon a pour conséquence :","o":["Une meilleure généralisation des résultats","Plus de validité interne, moins de généralisation","Une perte de validité interne, par excès de contrôle","Une augmentation des biais de mesure"],"r":1,"e":"C'est la conséquence directe de critères d'éligibilité rigoureux : l'échantillon ressemble de moins en moins à la population réelle.","s":2},{"q":"Les phases du processus de recherche sont décrites comme :","o":["Totalement indépendantes, sans aucun retour en arrière","Liées entre elles, avec des retours en arrière fréquents","Strictement successives, dans un ordre fixe","Interchangeables, dans n'importe quel ordre"],"r":1,"e":"Découvrir en phase méthodologique qu'une variable est inmesurable oblige par exemple à reformuler la question posée en phase conceptuelle. Elles s'informent mutuellement.","s":2},{"q":"Une population se définit dans ce cours comme :","o":["L'ensemble des habitants d'un pays, recensés","Les éléments partageant les caractéristiques visées","Les patients d'un service, sur une année","Les participants effectivement recrutés, inclus"],"r":1,"e":"L'échantillon en est un sous-ensemble, qui doit être représentatif pour autoriser l'inférence à la population entière.","s":2},{"q":"La qualité essentielle que doit posséder un échantillon est :","o":["Sa grande taille, la plus grande possible","Sa représentativité de la population","Son homogénéité parfaite, en âge","Sa disponibilité, à tout moment"],"r":1,"e":"Un grand échantillon non représentatif reste biaisé : la taille améliore la précision, pas la justesse.","s":2},{"q":"La meilleure technique d'échantillonnage, selon le cours, est :","o":["L'échantillonnage de convenance","L'échantillonnage aléatoire, probabiliste","Le volontariat, sur la base d'une annonce publique","La sélection par le clinicien"],"r":1,"e":"Elle seule donne à chaque élément une probabilité connue d'être sélectionné, ce qui fonde la validité de l'inférence statistique.","s":2},{"q":"La phase méthodologique couvre notamment :","o":["Le design, la population, l'échantillonnage, le recueil","La revue de la littérature, critique","L'interprétation des résultats et la discussion des limites","La rédaction de l'article, pour une revue"],"r":0,"e":"Elle définit toutes les décisions techniques avant tout recueil : c'est le moment où les biais peuvent encore être prévenus par le design. Elle couvre aussi les critères d'éligibilité et l'analyse.","s":2},{"q":"Les Core Outcome Sets ont pour fonction :","o":["De limiter le nombre de participants inclus par étude","De fixer un socle minimal de résultats à mesurer","De standardiser les interventions testées","De fixer les critères d'éligibilité"],"r":1,"e":"Leur adoption rend les études comparables et rend possibles les méta-analyses, souvent empêchées par l'hétérogénéité des outcomes choisis. Ces résultats sont mesurés dans les études d'un domaine donné.","s":2},{"q":"La qualité de vie et la satisfaction relèvent des résultats :","o":["Cliniques","Humanistiques","Économiques","Méthodologiques"],"r":1,"e":"Ils s'apprécient dans la perspective des patients, des familles et des aidants — celle qui compte le plus pour juger d'un bénéfice réel.","s":2},{"q":"La quatrième phase du processus de recherche correspond :","o":["À l'analyse des données recueillies","À la diffusion et au partage des résultats","À la formulation de la question, et à sa justification","Au choix du design de l'étude"],"r":1,"e":"Une recherche non diffusée n'ajoute rien à la connaissance collective : c'est le sens de l'image de la brique ajoutée au mur.","s":2},{"q":"Le F de FINER interroge la faisabilité au regard :","o":["Des participants, des méthodes, du temps et des coûts","De l'intérêt scientifique, pour les pairs","De l'éthique, et du consentement des patients","De la nouveauté, pour la connaissance existante"],"r":0,"e":"Un projet passionnant mais irréalisable dans les conditions disponibles échoue avant même de commencer : cette lettre vient en premier pour cette raison.","s":2},{"q":"Comment le cours définit-il la validité ?","o":["La reproductibilité d'une mesure, d'un jour à l'autre","Des résultats vrais, qui mesurent ce qu'ils doivent","La taille suffisante de l'échantillon, pour la puissance","L'absence de tout conflit d'intérêts"],"r":1,"e":"La validité signifie que ce que je fais dans l'étude, les résultats reflètent la vérité et mesurent ce qui est censé être mesuré.","s":3},{"q":"Que désigne la validité interne ?","o":["La généralisation des résultats à toute la population","La fiabilité des conclusions pour l'échantillon étudié","La qualité de la revue de la littérature","Le respect du protocole éthique"],"r":1,"e":"La validité interne est le degré de fiabilité du fait que les conclusions d'une étude sont valides pour l'échantillon étudié, et la capacité d'affirmer que les résultats et la relation des variables sont réels.","s":3},{"q":"Que désigne la validité externe ?","o":["L'application des conclusions à la population","La rigueur du contrôle des variables","L'absence d'erreur de mesure, aléatoire","La comparabilité des groupes, au départ"],"r":0,"e":"La validité externe est l'applicabilité des conclusions d'une étude à la population, c'est-à-dire la généralisation des résultats. C'est la généralisation des résultats.","s":3},{"q":"Par quoi la validité externe peut-elle être affectée ?","o":["Par des erreurs de sélection des participants","Par le choix du test statistique utilisé","Par la taille de l'effet observé","Par l'absence d'aveuglement de l'évaluateur"],"r":0,"e":"La validité externe peut être affectée par des erreurs de sélection des participants ; la validité interne, elle, par des erreurs systématiques dans la mesure ou la relation entre variables.","s":3},{"q":"Qu'est-ce qu'un biais ?","o":["Une erreur aléatoire, due au seul hasard de la mesure","Une erreur systématique, qui écarte de la vérité","Une différence entre deux groupes","Une faute de calcul statistique"],"r":1,"e":"Le biais est une erreur systématique : un processus pouvant survenir à n'importe quel moment de l'étude et qui tend à produire des résultats systématiquement différents des valeurs réelles, menaçant la validité interne. Elle menace la validité interne.","s":3},{"q":"Quels sont les trois types de biais cités ?","o":["Selection bias, measurement bias et confounding bias","Publication bias, recall bias et attrition bias","Random bias, fixed bias et mixed bias","Bias primaire, secondaire et tertiaire"],"r":0,"e":"Le cours cite le selection bias (sélection des participants), le measurement bias (mesure et recueil des données) et le confounding bias (relation entre variables).","s":3},{"q":"Qu'est-ce que la précision selon le cours ?","o":["Une erreur systématique, évitable par le design","Une erreur aléatoire, inhérente à toute observation","La finesse de l'instrument de mesure utilisé","La validité externe de l'étude, en population"],"r":1,"e":"La précision est associée à l'erreur de mesure : il y a toujours une divergence entre résultats observés et valeur vraie, inhérente à toutes les observations et résultant du hasard. Elle résulte du hasard.","s":3},{"q":"Quelle différence essentielle sépare biais et erreur aléatoire ?","o":["Le biais se prévient, l'erreur aléatoire jamais","Le biais ne se corrige pas, l'erreur si","Les deux peuvent être totalement éliminées","Aucune, ce sont deux synonymes"],"r":0,"e":"L'erreur systématique peut être prévue, prévenue et minimisée ; l'erreur aléatoire ne peut jamais être éliminée, seulement minimisée et estimée par l'analyse statistique.","s":3},{"q":"Comment peut-on minimiser l'erreur aléatoire ?","o":["Par l'aveuglement des évaluateurs","Par une plus grande taille d'échantillon","Par une meilleure randomisation","Par des critères d'inclusion stricts"],"r":1,"e":"L'erreur aléatoire peut être minimisée, par exemple par la taille de l'échantillon, et son effet doit être estimé par l'analyse statistique (valeur p). Son effet est estimé par l'analyse statistique (valeur p).","s":3},{"q":"Que signifie l'acronyme RAMBOMAN ?","o":["Recrutement, Allocation, Maintien, Aveuglement, Objectif, Mesures, Analyse","Randomisation, Analyse, Méthode, Biais, Outcome, Manipulation, Anonymat","Revue, Article, Méthode, Base, Objectif, Mesure, Analyse","Résultats, Approche, Modèle, Bilan, Observation, Méta, Analyse"],"r":0,"e":"RAMBOMAN = Recrutement, Allocation, Maintien, Aveuglement/dissimulation, Objectif, Mesures, ANalyse.","s":3},{"q":"Quand utilise-t-on des études observationnelles ?","o":["Quand on veut prouver une causalité","Quand on ne peut pas manipuler les variables","Quand le budget est illimité","Quand l'échantillon est très homogène, et de grande taille"],"r":1,"e":"Les études observationnelles sont utilisées quand il n'est pas possible, ou n'a pas de sens, de manipuler des variables : on mesure des variables, il n'y a pas d'intervention. Ou quand la manipulation n'aurait pas de sens.","s":3},{"q":"Quel est le principal inconvénient des études observationnelles ?","o":["Leur coût très élevé, par participant","L'exposition n'est pas contrôlée, d'où plus de biais","Elles sont toujours très lentes, sur des années","Elles exigent une randomisation complexe et coûteuse"],"r":1,"e":"Les inconvénients sont l'absence de contrôle des conditions d'exposition et un plus grand potentiel de biais des résultats.","s":3},{"q":"Dans une étude de cohorte, que fait le chercheur ?","o":["Il évalue l'exposition avant l'outcome","Il évalue l'outcome avant l'exposition","Il évalue les deux en même temps","Il manipule lui-même l'intervention"],"r":0,"e":"Dans les études de cohorte, on évalue l'influence d'une exposition sur le développement de la maladie : on part de la cause pour identifier la conséquence, l'exposition étant évaluée avant l'outcome. Il part de la cause pour identifier la conséquence.","s":3},{"q":"Dans une étude cas-témoins, que fait le chercheur ?","o":["Il suit un groupe exposé et un groupe non exposé","Il cherche la cause d'un effet connu, après coup","Il randomise les participants, en double aveugle strict","Il évalue exposition et outcome en même temps"],"r":1,"e":"Dans les études cas-témoins, on mesure rétrospectivement l'exposition : l'effet est déjà connu et on cherche à identifier la cause. L'exposition est mesurée rétrospectivement.","s":3},{"q":"Qu'est-ce qui caractérise une étude transversale ?","o":["Plusieurs évaluations, à des moments différents","Une seule évaluation, outcome et exposition ensemble","Un suivi prospectif d'une cohorte, sur des années","Une randomisation des participants"],"r":1,"e":"L'étude transversale (cross sectional) comporte une évaluation UNE seule fois, sans suivi ; l'outcome est évalué en même temps que l'exposition. Il n'y a aucun suivi.","s":3},{"q":"Quel design convient aux questions de diagnostic et de fréquence ?","o":["Les études transversales","Les études cas-témoins","Les études de cohorte","Les essais cliniques"],"r":0,"e":"Les études transversales correspondent aux questions de diagnostic et de fréquence.","s":3},{"q":"Quel design convient aux questions d'intervention ?","o":["Les études transversales","Les études cas-témoins","Les essais cliniques","Les études de prévalence"],"r":2,"e":"Les essais cliniques correspondent aux questions d'intervention.","s":3},{"q":"Une étude où l'on identifie un groupe avec l'outcome et un groupe sans, puis où l'on remonte dans le temps, est :","o":["Une cohorte","Une étude cas-témoins","Une étude transversale","Un essai randomisé"],"r":1,"e":"C'est une étude cas-témoins : on identifie un groupe avec présence de l'outcome et un autre sans, puis on remonte dans le temps pour comprendre quel facteur de risque a pu influencer la maladie.","s":3},{"q":"Si le chercheur ne manipule pas l'exposition et enregistre l'outcome APRÈS l'exposition, l'étude est :","o":["Transversale","Une cohorte","Cas-témoins","Un ECR"],"r":1,"e":"Dans l'arbre décisionnel, si l'outcome est enregistré après l'exposition, il s'agit d'une cohorte.","s":3},{"q":"Une étude qui décrit la population relève de quelle approche ?","o":["Analytique et quantitative","Descriptive et qualitative","Expérimentale","Méthodologique"],"r":1,"e":"Si l'étude décrit la population, elle est descriptive (recherche qualitative) ; si elle quantifie la relation entre variables, elle est analytique (recherche quantitative).","s":3},{"q":"Quelle est la différence entre un ECR et un N-ECR ?","o":["Le N-ECR n'a pas de groupe contrôle","Seul l'ECR a une allocation randomisée","Le N-ECR est une étude observationnelle","Le N-ECR n'a pas d'intervention, seulement une mesure"],"r":1,"e":"Dans une étude expérimentale, si l'allocation est aléatoire ou randomisée, c'est un ECR ; si elle ne l'est pas, c'est un N-ECR.","s":3},{"q":"Quel est l'objectif de la randomisation ?","o":["Réduire le coût de l'étude","Rendre les groupes comparables","Augmenter la taille de l'échantillon","Permettre l'aveuglement du statisticien"],"r":1,"e":"La randomisation attribue aléatoirement les participants à l'intervention qu'ils vont recevoir, avec pour objectif de rendre les groupes comparables.","s":3},{"q":"Qu'est-ce que l'allocation concealment ?","o":["L'anonymisation des données recueillies","La dissimulation de la séquence d'allocation","Cacher les résultats jusqu'à la publication","L'aveuglement de l'évaluateur, et du patient traité"],"r":1,"e":"La séquence d'allocation doit être dissimulée aux chercheurs (allocation concealment), en utilisant par exemple des enveloppes scellées. On utilise par exemple des enveloppes scellées.","s":3},{"q":"Qu'est-ce qu'un aveuglement en double insu ?","o":["Le participant seul est aveuglé","Le participant et le chercheur sont aveuglés","Le participant, le chercheur et l'évaluateur sont aveuglés","Le statisticien seul est aveuglé"],"r":1,"e":"L'aveuglement simple concerne le participant, le double le participant et le chercheur, le triple le participant, le chercheur et l'évaluateur.","s":3},{"q":"Qu'est-ce qu'une étude quasi-expérimentale ?","o":["Une étude sans aucune manipulation de variables","Une manipulation sans contrôle ou sans randomisation","Un essai randomisé de petite taille","Une revue systématique, sans méta-analyse"],"r":1,"e":"Les études quasi-expérimentales comportent une manipulation de variables, mais sans groupe de contrôle ou sans randomisation : ce sont des études de moindre rigueur et qualité méthodologique. C'est une étude de moindre rigueur méthodologique.","s":3},{"q":"Quel est un inconvénient des études expérimentales ?","o":["Un plus grand potentiel de biais, en pratique","Une généralisation limitée, les sujets étant triés","L'absence de contrôle sur l'intervention appliquée","L'impossibilité d'établir une relation causale"],"r":1,"e":"Les inconvénients sont la généralisation limitée (participants très sélectionnés), la difficulté de recrutement, les questions éthiques, les coûts plus élevés et la logistique complexe.","s":3},{"q":"Comment se comparent ECR et real world studies en validité interne ?","o":["ECR élevée, real world basse","ECR basse, real world élevée","Les deux élevées","Les deux basses"],"r":0,"e":"Les ECR ont une validité interne élevée et une validité externe basse ; les real world studies ont l'inverse.","s":3},{"q":"Comment définit-on l'efficacité ?","o":["Le résultat du traitement dans son environnement réel","Une propriété intrinsèque d'une conduite biomédicale","Le rapport entre le bénéfice et le coût d'un traitement","La satisfaction du patient, mesurée en fin de traitement"],"r":1,"e":"L'efficacité est une propriété intrinsèque d'une conduite biomédicale ; l'effectivité est le résultat de l'interaction du traitement avec l'environnement d'application.","s":3},{"q":"Quel est le meilleur niveau de preuve pour répondre à une question d'effectivité ?","o":["Les essais contrôlés randomisés","Les études en vie réelle, observationnelles","Les études de cas, détaillées et en grand nombre","Les avis d'experts, consensuels"],"r":1,"e":"Le meilleur niveau de preuve pour l'efficacité, ce sont les ECR ; pour l'effectivité, ce sont les real world studies (observationnelles).","s":3},{"q":"Quelle phrase résume le rapport entre efficacité et effectivité ?","o":["L'efficacité garantit toujours l'effectivité, en pratique","L'efficacité ne se traduit pas toujours en effectivité","L'effectivité précède toujours l'efficacité","Les deux notions sont strictement équivalentes"],"r":1,"e":"Le cours conclut que l'efficacité ne se traduit pas toujours en effectivité.","s":3},{"q":"Les trois grandes catégories d'études distinguées par le cours sont :","o":["Primaires, secondaires et méthodologiques","Quantitatives, qualitatives et mixtes","Observationnelles, expérimentales et descriptives","Prospectives, rétrospectives et transversales"],"r":0,"e":"Les primaires regroupent expérimentales et observationnelles ; les secondaires les scoping reviews, revues systématiques, méta-analyses et guidelines ; les méthodologiques la construction et la validation d'instruments.","s":3},{"q":"La validité interne peut être affectée par :","o":["Des erreurs de sélection des participants","Des erreurs systématiques de mesure ou de relation","Une taille d'échantillon trop faible, uniquement","Le choix du logiciel statistique, payant"],"r":1,"e":"La validité externe, elle, peut être affectée par des erreurs de sélection des participants, qui compromettent la généralisation à la population. La relation en cause est celle entre les variables.","s":3},{"q":"L'exemple « les résultats ne s'appliquent pas à notre patient de 17 ans, l'échantillon comptant des adultes de plus de 18 ans » illustre un problème :","o":["De validité interne","De validité externe","De précision","De biais de mesure"],"r":1,"e":"L'étude peut être parfaitement conduite et ses conclusions vraies pour son échantillon : c'est leur transposition à ce patient qui fait défaut.","s":3},{"q":"Un biais se distingue d'une erreur aléatoire parce qu'il :","o":["Résulte du seul hasard, à chaque mesure effectuée","Est systématique, et peut être prévenu","Ne peut jamais être minimisé, ni corrigé","N'affecte que la validité externe"],"r":1,"e":"L'erreur aléatoire ne peut jamais être éliminée : elle est inhérente à toute observation. Seule son ampleur peut être réduite et son effet estimé. Il peut être prévu et prévenu dans le design.","s":3},{"q":"Le confounding bias concerne :","o":["La sélection des participants","La mesure des variables","La relation entre variables","L'analyse statistique"],"r":2,"e":"Les trois types sont le selection bias, sur le recrutement, le measurement bias, sur le recueil des données, et le confounding bias, sur la relation entre variables.","s":3},{"q":"L'effet de l'erreur aléatoire est estimé par :","o":["La valeur p","Le calcul du biais","La randomisation","L'aveuglement"],"r":0,"e":"Elle se minimise notamment par l'augmentation de la taille de l'échantillon, mais aucune conception d'étude ne peut la supprimer.","s":3},{"q":"Le M final de l'acronyme RAMBOMAN correspond à :","o":["Maintien","Mesures","Manipulation","Méthode"],"r":1,"e":"L'acronyme complet : Recrutement, Allocation, Maintien, Blinding, Objectif, Mesures, ANalyse. Le maintien correspond au premier M.","s":3},{"q":"Les études observationnelles sont indiquées quand :","o":["On veut prouver une causalité, de façon certaine","On ne peut pas manipuler les variables","On dispose de beaucoup de moyens","L'échantillon est très grand"],"r":1,"e":"Elles offrent moins de limitations éthiques et pratiques, sont moins coûteuses et plus rapides, mais exposent à un plus grand potentiel de biais. Ou quand cette manipulation n'a pas de sens.","s":3},{"q":"Dans une étude de cohorte, l'exposition est évaluée :","o":["Après l'outcome, rétrospectivement","Avant l'outcome, de la cause vers l'effet","En même temps que l'outcome","Jamais, l'exposition n'étant pas du tout mesurée"],"r":1,"e":"L'étude cas-témoins procède en sens inverse : l'effet est déjà connu et l'on recherche rétrospectivement la cause.","s":3},{"q":"Une étude transversale se caractérise par le fait que :","o":["L'exposition précède l'outcome","L'outcome précède l'exposition, rétrospectivement","Les deux sont évalués ensemble, une seule fois","Aucune variable n'est mesurée"],"r":2,"e":"Cette simultanéité interdit d'établir une chronologie, donc de conclure à une causalité — mais convient aux questions de diagnostic et de fréquence.","s":3},{"q":"Selon la correspondance question-design, les questions d'étiologie et de pronostic appellent :","o":["Une étude transversale, unique","Une étude cas-témoins ou de cohorte","Un essai clinique randomisé","Une revue systématique des essais"],"r":1,"e":"Les questions de diagnostic et de fréquence appellent une étude transversale, les questions d'intervention un essai clinique.","s":3},{"q":"Un essai contrôlé randomisé associe :","o":["Manipulation et randomisation, sans groupe contrôle","Manipulation, groupe de contrôle et randomisation","Groupe de contrôle et randomisation, sans manipulation","Observation et suivi longitudinal"],"r":1,"e":"Une étude quasi-expérimentale comporte la manipulation mais lui manque soit le groupe de contrôle, soit la randomisation — d'où une moindre rigueur.","s":3},{"q":"L'aveuglement triple concerne :","o":["Le participant, le chercheur et l'évaluateur","Le participant et le chercheur","Le chercheur, l'évaluateur et le statisticien","Le participant seul"],"r":0,"e":"Le simple insu ne concerne que le participant, le double y ajoute le chercheur ; on peut aller au-delà en aveuglant aussi le statisticien.","s":3},{"q":"L'allocation concealment consiste à :","o":["Cacher le traitement reçu au patient, pendant toute l'étude","Dissimuler la séquence d'allocation aux chercheurs","Masquer les résultats à l'évaluateur","Randomiser après l'inclusion du patient"],"r":1,"e":"Si l'investigateur peut deviner le groupe suivant, il risque d'orienter les inclusions — ce qui détruit l'équilibre que la randomisation devait produire. On utilise par exemple des enveloppes scellées.","s":3},{"q":"Les essais contrôlés randomisés se caractérisent par :","o":["Une validité interne élevée et une validité externe basse","Une validité interne basse et une validité externe élevée","Les deux validités élevées","Les deux validités basses"],"r":0,"e":"Les real world studies présentent le profil inverse : conditions réelles donc bonne généralisation, mais contrôle faible des facteurs de confusion.","s":3},{"q":"L'efficacité, au sens du cours, se définit comme :","o":["Le résultat du traitement dans son environnement d'application","Une propriété intrinsèque d'une conduite biomédicale","Le rapport entre le coût et le bénéfice","La satisfaction du patient, en fin de traitement"],"r":1,"e":"Son meilleur niveau de preuve est l'essai contrôlé randomisé. L'effectivité, elle, s'évalue au mieux par les real world studies.","s":3},{"q":"Le cours souligne à propos du couple efficacité / effectivité que :","o":["Les deux se confondent en pratique, toujours","L'efficacité ne garantit pas l'effectivité","L'effectivité précède toujours l'efficacité","Seule l'efficacité compte en clinique, en pratique"],"r":1,"e":"Un traitement peut fonctionner dans les conditions idéales d'un essai et décevoir en pratique courante — du fait de l'observance, des comorbidités ou de l'organisation des soins.","s":3},{"q":"Les études observationnelles présentent comme avantage :","o":["La participation des individus en contexte naturel","Un contrôle strict des conditions d'exposition","Une absence totale de biais","Une preuve de causalité"],"r":0,"e":"Leur inconvénient principal est précisément l'absence de contrôle des conditions d'exposition, d'où un potentiel de biais accru.","s":3},{"q":"La précision d'une étude est associée à :","o":["L'erreur systématique, évitable","L'erreur de mesure, due au hasard","La sélection des participants, à l'inclusion","La validité externe, en population"],"r":1,"e":"Il existe toujours une divergence entre résultat observé et valeur vraie. Cette imprécision affecte l'estimation, non la direction du résultat. Cette erreur est inhérente à toute observation.","s":3},{"q":"Une étude où le chercheur identifie un groupe avec l'outcome et un groupe sans, puis recherche l'exposition passée, est :","o":["Une cohorte","Une étude cas-témoins","Une étude transversale","Un essai randomisé"],"r":1,"e":"C'est le design de choix pour les événements rares : partir de l'effet permet de constituer un groupe suffisant, ce qu'une cohorte exigerait d'immense.","s":3},{"q":"Qu'est-ce qui caractérise une revue de la littérature simple ?","o":["Elle est réalisée sans critères d'éligibilité","Elle évalue systématiquement le risque de biais","Elle combine statistiquement les résultats","Elle nécessite un enregistrement PROSPERO"],"r":0,"e":"La revue de la littérature se fait sans critères d'éligibilité, contrairement à la revue systématique.","s":4},{"q":"Qu'est-ce qu'une umbrella review ?","o":["Une revue sur un sujet très large","Une revue des revues systématiques","Une revue rapide multicentrique","Une méta-analyse de données individuelles"],"r":1,"e":"L'umbrella review est une revue des revues systématiques.","s":4},{"q":"Quelle caractéristique définit la rapid review ?","o":["Elle n'a qu'un relecteur et saute des étapes","Elle suit exactement le protocole PRISMA","Elle inclut toujours une méta-analyse complète des essais","Elle exige au moins trois évaluateurs"],"r":0,"e":"La rapid review exclut certaines étapes d'une RS, synthétise de façon descriptive, n'utilise qu'un seul relecteur et il n'existe pas de critères standard pour sa réalisation. Elle exclut certaines étapes de la revue systématique.","s":4},{"q":"Quel est l'objet principal d'une scoping review ?","o":["Mesurer l'efficacité d'une intervention","Cartographier la littérature d'un domaine","Combiner statistiquement les essais","Produire des recommandations cliniques, graduées"],"r":1,"e":"La scoping review est une cartographie de la littérature dans un domaine d'intérêt déterminé ; elle n'est pas focalisée sur les effets et caractérise une intervention de santé.","s":4},{"q":"Quelle différence majeure sépare scoping review et revue systématique ?","o":["Seule la systématique évalue la qualité des études","La scoping review est plus complète et plus exhaustive","La systématique n'a pas de critères d'éligibilité","La scoping inclut toujours une méta-analyse"],"r":0,"e":"La scoping review n'évalue pas la qualité des études ; la revue systématique évalue la qualité méthodologique des articles et est plus complète. La scoping review n'évalue pas la qualité méthodologique.","s":4},{"q":"Quelle stratégie de question correspond aux scoping reviews ?","o":["PICOT","PECOT","PCC","POT"],"r":2,"e":"PCC — Population, Concept, Contexte — s'applique aux scoping reviews. PCC : Population, Concept, Contexte.","s":4},{"q":"Lequel de ces objectifs n'appartient PAS à la scoping review ?","o":["Évaluer l'étendue et la nature des études scientifiques","Identifier la faisabilité de réaliser une revue systématique","Identifier les lacunes de la littérature","Établir la supériorité statistique d'une intervention"],"r":3,"e":"La scoping review n'est pas focalisée sur les effets : elle cartographie, clarifie des concepts, évalue la faisabilité d'une RS et identifie les lacunes.","s":4},{"q":"Qui est à l'origine de la revue systématique en 1979 ?","o":["Archie Cochrane","David Sackett","Iain Chalmers","Gordon Guyatt"],"r":0,"e":"Archie Cochrane, en 1979, critiquait l'absence d'un résumé critique adapté périodiquement de tous les essais cliniques randomisés pertinents.","s":4},{"q":"Comment le cours définit-il la revue systématique ?","o":["Une synthèse narrative des publications d'un domaine","Une revue à critères définis, aux méthodes reproductibles","Un avis d'experts structuré, en plusieurs tours de consensus","Une compilation de guidelines, nationales"],"r":1,"e":"La RS recueille l'évidence scientifique selon des critères d'éligibilité définis pour répondre à une question clinique spécifique, en utilisant des méthodes explicites, reproductibles et systématisées afin de minimiser le risque de biais. Elle répond à une question clinique spécifique, avec des méthodes explicites qui minimisent le risque de biais.","s":4},{"q":"Combien de phases comporte la réalisation d'une revue systématique selon le cours ?","o":["5","7","9","12"],"r":2,"e":"Le cours détaille 9 phases, de la définition de la question à l'interprétation des résultats et aux recommandations.","s":4},{"q":"Combien de temps peut prendre le processus complet d'une revue systématique ?","o":["Quelques jours","Environ un mois","Plus d'un an","Au moins cinq ans"],"r":2,"e":"Le cours précise que compléter tout le processus d'une RS peut prendre plus d'un an.","s":4},{"q":"Sur quelle plateforme enregistre-t-on le titre d'une revue systématique ?","o":["PROSPERO","PRISMA","AMSTAR","Rayyan"],"r":0,"e":"L'enregistrement du titre des revues systématiques se fait sur PROSPERO.","s":4},{"q":"Quelle stratégie de question est utilisée en phase 1 d'une revue systématique ?","o":["PCC","PICOS","POT","PICo"],"r":1,"e":"La phase 1 de la revue systématique définit la question de recherche avec le PICOS.","s":4},{"q":"Que produisent des critères d'éligibilité plus stricts ?","o":["Ils évitent l'hétérogénéité et diminuent le biais","Ils augmentent l'hétérogénéité des études","Ils réduisent la validité interne de la revue","Ils augmentent le nombre d'études incluses"],"r":0,"e":"Des critères plus stricts évitent l'hétérogénéité des études et diminuent le biais ; des critères plus souples incluent des études hétérogènes et explorent l'évidence disponible.","s":4},{"q":"Combien de bases de données au minimum le cours recommande-t-il ?","o":["Une seule","Au moins 2","Au moins 3","Au moins 5"],"r":2,"e":"La stratégie de recherche doit couvrir au moins 3 bases de données, avec 2 ou 3 évaluateurs.","s":4},{"q":"Comment se fait la sélection des études en phase 4 ?","o":["Par un seul chercheur, de façon rapide et non aveugle","Par deux chercheurs aveugles, un troisième si besoin","Automatiquement, par un logiciel","Par le comité d'éthique, en séance"],"r":1,"e":"La sélection repose sur l'évaluation des titres et abstracts par deux chercheurs indépendants aveugles, avec un 3e chercheur pour consensus si nécessaire et un niveau de concordance entre évaluateurs. On évalue titres et abstracts, avec un niveau de concordance entre évaluateurs.","s":4},{"q":"Quel outil facilite la sélection des études d'une revue systématique ?","o":["Rayyan","AMSTAR","GRADE","PROSPERO"],"r":0,"e":"Rayyan est cité comme outil d'aide pour la sélection des études, avec le diagramme de flux.","s":4},{"q":"Combien d'évaluateurs au minimum pour l'évaluation de la qualité des études (phase 7) ?","o":["Un seul évaluateur, suffisant","Au moins deux, avec un calcul de concordance","Au moins quatre, avec un vote à la majorité simple","Le nombre est libre, selon les moyens"],"r":1,"e":"L'analyse indépendante se fait par au moins 2 évaluateurs, avec calcul du niveau de concordance (k), suivie d'une réunion de consensus. La concordance se mesure par le coefficient kappa, puis une réunion de consensus a lieu.","s":4},{"q":"Que signifie GRADE ?","o":["Grading of Recommendations Assessment, Development and Evaluation","General Research Assessment of Data and Evidence","Guideline Rating, Assessment, Development and Global Evaluation","Global Risk Assessment of Diagnostic Evidence"],"r":0,"e":"GRADE signifie Grading of Recommendations Assessment, Development and Evaluation : c'est l'évaluation de la certitude de l'évidence.","s":4},{"q":"Lequel de ces domaines N'EST PAS un domaine de GRADE ?","o":["Incohérence","Évidence indirecte","Biais de publication","Budget de l'étude"],"r":3,"e":"Les cinq domaines de GRADE sont : limites de l'étude/risque de biais, incohérence, évidence indirecte, imprécision et biais de publication. Les autres domaines sont les limites des études (risque de biais) et l'imprécision.","s":4},{"q":"En quoi doit être divisée la conclusion d'une revue systématique ?","o":["En points forts et points faibles","En implications cliniques et pour la recherche","En résultats positifs et négatifs","En sections méthodologique, statistique et clinique"],"r":1,"e":"La conclusion d'une revue systématique devra être divisée en implications pour la pratique clinique et implications pour la recherche.","s":4},{"q":"Quelle checklist sert à rapporter une revue systématique ?","o":["CONSORT","PRISMA","STROBE","CARE"],"r":1,"e":"PRISMA est la guideline et checklist de référence pour rapporter les revues systématiques, avec son diagramme de flux.","s":4},{"q":"À quoi sert AMSTAR ?","o":["À rapporter un essai clinique randomisé","À évaluer la qualité des revues systématiques","À calculer la taille d'échantillon","À enregistrer un protocole de revue"],"r":1,"e":"AMSTAR (A MeaSurement Tool to Assess systematic Reviews) sert, avec la CASP Checklist, à évaluer la qualité et le risque de biais des revues systématiques. Il évalue aussi leur risque de biais, comme la CASP Checklist.","s":4},{"q":"Que signifie le H du FAITH check ?","o":["Les hypothèses sont-elles posées ?","Les résultats sont-ils hétérogènes ?","La population est-elle homogène ?","Les études incluses sont-elles de haute qualité ?"],"r":1,"e":"Le H du FAITH check pose la question : les résultats sont-ils hétérogènes ?","s":4},{"q":"Quel outil le FAITH check recommande-t-il d'utiliser pour évaluer les études individuellement ?","o":["Le RAMBOMAN","Le GRADE","Le PRISMA","Le CONSORT"],"r":0,"e":"Le A du FAITH check — ont-ils évalué les études individuellement ? — renvoie à l'utilisation du RAMBOMAN.","s":4},{"q":"Combien d'études primaires minimum une méta-analyse intègre-t-elle ?","o":["Deux","Trois ou plus","Cinq ou plus","Dix ou plus"],"r":1,"e":"La méta-analyse est la méthode statistique incluse dans une RS qui intègre les résultats de trois études primaires ou plus.","s":4},{"q":"Quelle est la différence d'analyse entre revue systématique et méta-analyse ?","o":["La RS juge chaque étude, la méta-analyse les combine","La RS est quantitative, la méta-analyse qualitative","Les deux sont purement qualitatives, étude par étude","Les deux sont purement quantitatives, sur l'ensemble"],"r":0,"e":"La revue systématique fait une analyse qualitative de chaque étude individuellement ; la méta-analyse fait une analyse quantitative, analysant les études ensemble et sommant l'effet. La revue systématique fait une analyse qualitative ; la méta-analyse, une analyse quantitative.","s":4},{"q":"Dans quel cas NE faut-il PAS réaliser de méta-analyse ?","o":["Si les questions diffèrent trop, ou si les biais sont lourds","Quand il y a plus de dix études, à combiner","Quand les études sont très semblables, en population et en design","Quand l'effet est important, et cohérent"],"r":0,"e":"Il ne faut pas faire de méta-analyse en cas de variations significatives des questions cliniques, quand la diversité des études prive les résultats de signification réelle, ou si les études ont des biais importants.","s":4},{"q":"Que montre un forest plot ?","o":["Le diagramme de flux de la sélection","L'hétérogénéité et l'effet commun estimé","La certitude de l'évidence, selon GRADE","La chronologie des publications, de la plus ancienne"],"r":1,"e":"Le forest plot résume les informations des études individuellement, donne une suggestion visuelle de l'hétérogénéité et montre l'effet commun estimé, indiquant si l'intervention est bénéfique ou non.","s":4},{"q":"Comment le cours présente-t-il les guidelines ?","o":["Des ordres à respecter aveuglément, sans discussion","Des règles de bonne pratique, discutables mais à respecter","Des documents indicatifs, sans aucune valeur réelle","Des consensus d'experts, sans aucune base scientifique solide"],"r":1,"e":"Les guidelines ne sont pas des ordres aveugles : ce sont des règles de bonne pratique clinique, qui peuvent être discutées, diffusées et doivent être respectées.","s":4},{"q":"Une umbrella review est :","o":["Une revue de la littérature, sans critères","Une revue des revues systématiques","Une revue rapide, avec un seul relecteur","Une cartographie de la littérature"],"r":1,"e":"Les cinq types recensés : revue de la littérature, revue rapide, scoping review, revue systématique avec ou sans méta-analyse, et umbrella review.","s":4},{"q":"La revue rapide se caractérise notamment par :","o":["Un seul relecteur, et pas de critères standard","Une évaluation exhaustive du risque de biais","Trois relecteurs indépendants, aveugles","Un enregistrement obligatoire sur PROSPERO, avant le début"],"r":0,"e":"Elle exclut certaines étapes d'une revue systématique et synthétise les résultats de façon descriptive. Le cours cite la pandémie comme contexte typique d'usage.","s":4},{"q":"La scoping review n'évalue pas :","o":["L'étendue de la littérature","La qualité méthodologique des études","La nature des études incluses, et leur design","Les lacunes de la littérature"],"r":1,"e":"Elle cartographie sans juger : son objet est de caractériser une intervention et de délimiter un champ, non de conclure sur l'efficacité.","s":4},{"q":"La stratégie de question propre à la scoping review est :","o":["PICO","PCC","SPIDER","PEO"],"r":1,"e":"Population, Concept, Context. Les autres déclinaisons de PICO servent selon le type d'étude : qualitative, non expérimentale, de prévalence.","s":4},{"q":"Parmi les objectifs de la scoping review, le cours cite :","o":["Juger de la faisabilité d'une revue systématique","Calculer un effet commun, pondéré","Évaluer le risque de biais de chaque essai inclus","Formuler des recommandations de grade A"],"r":0,"e":"C'est un exercice préliminaire qui affine la question de revue. Elle sert aussi à clarifier des concepts et à repérer les lacunes de la littérature. Elle sert aussi à juger de la pertinence d'une telle revue.","s":4},{"q":"La revue systématique a pour caractéristique méthodologique essentielle :","o":["Des méthodes explicites et reproductibles","Rassembler toute la littérature, sans aucun tri","Se limiter aux seuls essais randomisés","Être réalisée par un seul auteur"],"r":0,"e":"Elle recueille l'évidence selon des critères d'éligibilité définis pour répondre à une question clinique spécifique, et évalue la qualité méthodologique des articles inclus. Ces méthodes systématisées minimisent le risque de biais.","s":4},{"q":"L'origine de la revue systématique est attribuée à :","o":["Sackett, 2000","Archie Cochrane, 1979","Beaton, 2000","Rothstein, 1995"],"r":1,"e":"La collaboration Cochrane, qui porte son nom, constitue aujourd'hui la référence méthodologique pour la réalisation des revues systématiques.","s":4},{"q":"La revue systématique comporte, selon le cours :","o":["5 phases","7 phases","9 phases","12 phases"],"r":2,"e":"De la question aux recommandations, en passant par critères d'éligibilité, stratégie de recherche, sélection, filtrage, extraction, évaluation de la qualité et analyse. Le processus peut dépasser un an.","s":4},{"q":"L'enregistrement du titre d'une revue systématique se fait sur :","o":["PRISMA","PROSPERO","AMSTAR","GRADE"],"r":1,"e":"Les jalons de publication se suivent dans cet ordre : enregistrer le titre, publier le protocole, publier la revue, publier la mise à jour.","s":4},{"q":"La stratégie de recherche d'une revue systématique exige au minimum :","o":["Une base de données","Deux bases de données","Trois bases de données","Cinq bases de données"],"r":2,"e":"S'y ajoutent les mots-clés et leurs combinaisons, le choix entre texte intégral et résumés, et le recours à deux ou trois évaluateurs.","s":4},{"q":"La sélection des articles dans une revue systématique se fait :","o":["Par un seul chercheur, qui trie tout seul et vite","Par deux chercheurs aveugles, puis un troisième","Par vote majoritaire de l'équipe","Automatiquement, par un logiciel"],"r":1,"e":"Le niveau de concordance entre évaluateurs, mesuré par le coefficient kappa, documente la fiabilité de cette étape. Le troisième chercheur intervient pour le consensus.","s":4},{"q":"GRADE évalue la certitude de l'évidence selon :","o":["Trois domaines","Quatre domaines","Cinq domaines","Sept domaines"],"r":2,"e":"Limites de l'étude ou risque de biais, incohérence, évidence indirecte, imprécision et biais de publication.","s":4},{"q":"L'outil AMSTAR sert à :","o":["Rapporter une revue systématique","Évaluer la qualité d'une revue systématique","Sélectionner les articles à inclure","Analyser les données des essais, par méta-analyse"],"r":1,"e":"CASP remplit une fonction voisine. PRISMA est la guideline de rapport, Rayyan un outil de sélection, INSPECT-SR un détecteur d'essais problématiques.","s":4},{"q":"Une méta-analyse intègre les résultats :","o":["De deux études au minimum","De trois études primaires ou plus","De dix études au minimum","D'une seule étude de grande taille"],"r":1,"e":"C'est une méthode statistique incluse dans une revue systématique lorsque c'est pertinent, qui ajoute une évaluation quantitative à l'analyse qualitative.","s":4},{"q":"Le forest plot d'une méta-analyse :","o":["Classe les études par date de leur publication","Résume les études et montre l'effet commun estimé","Évalue le risque de biais de chaque étude","Présente la stratégie de recherche documentaire"],"r":1,"e":"Chaque étude y apparaît avec son effet et son intervalle de confiance ; le losange final synthétise l'estimation combinée.","s":4},{"q":"Les guidelines sont décrites dans le cours comme :","o":["Des ordres à appliquer aveuglément, sans discussion","Des règles de bonne pratique, à discuter","De simples suggestions, sans portée","Des textes réglementaires, opposables"],"r":1,"e":"Cette formulation équilibrée écarte deux erreurs symétriques : l'application mécanique et le rejet au nom de la liberté clinique. Elles doivent être respectées.","s":4},{"q":"La revue de la littérature se distingue des autres types de revue parce qu'elle :","o":["Applique des critères d'éligibilité stricts","Ne définit pas de critères d'éligibilité","Évalue le risque de biais","Inclut une méta-analyse"],"r":1,"e":"C'est cette absence de critères explicites qui la rend non reproductible : deux auteurs sur le même sujet n'aboutiraient pas au même corpus.","s":4},{"q":"Le domaine GRADE dit « évidence indirecte » concerne :","o":["Des études dont la population ou l'outcome diffèrent","Des résultats contradictoires entre études","Des intervalles de confiance larges, peu informatifs","Des études non publiées, négatives"],"r":0,"e":"L'incohérence désigne les résultats contradictoires, l'imprécision les intervalles larges, le biais de publication la non-publication des résultats négatifs. L'intervention peut aussi différer de la question posée.","s":4},{"q":"Le coefficient kappa, utilisé lors de la sélection des articles, mesure :","o":["La taille d'effet commune","La concordance entre évaluateurs","La qualité méthodologique des études","L'hétérogénéité des résultats"],"r":1,"e":"Une concordance faible signale des critères d'éligibilité mal définis, qu'il faut clarifier avant de poursuivre la sélection.","s":4},{"q":"L'outil Rayyan sert à :","o":["Évaluer le risque de biais","Faciliter la sélection des articles","Rédiger le rapport final","Réaliser la méta-analyse, avec un forest plot"],"r":1,"e":"Il permet à plusieurs relecteurs de trier les références en aveugle, puis de confronter leurs décisions — ce que la méthode exige explicitement.","s":4},{"q":"Comment le cours définit-il la mesure ?","o":["La quantification de caractéristiques précises","L'interprétation d'informations cliniques, subjectives","L'observation attentive du patient","La comparaison entre deux groupes"],"r":0,"e":"La mesure est la quantification de caractéristiques déterminées ; l'évaluation est le processus de sélection, recueil, analyse et interprétation d'information clinique.","s":5},{"q":"Qu'englobe l'évaluation selon le cours ?","o":["Les seules données objectives, mesurées en séance","Un processus portant sur le subjectif et l'objectif","Le seul ressenti du patient, auto-rapporté","Les seules mesures instrumentales, chiffrées"],"r":1,"e":"L'évaluation est le processus de sélection, recueil, analyse et interprétation d'information clinique, subjective et objective. C'est la sélection, le recueil, l'analyse et l'interprétation d'information clinique.","s":5},{"q":"Quel exemple correspond à un résultat clinique ?","o":["La qualité de vie, auto-évaluée","L'amplitude, le tonus, la force musculaire","Le nombre de séances, sur l'année","Le niveau de satisfaction du patient"],"r":1,"e":"Les résultats cliniques donnent la perspective des professionnels de santé : ROM, tonus, force musculaire.","s":5},{"q":"Quel exemple correspond à un résultat économique ?","o":["L'intensité de la douleur, à l'échelle visuelle","La productivité, le nombre de séances, les coûts","Le tonus musculaire, à l'échelle d'Ashworth modifiée","La qualité de vie, générique"],"r":1,"e":"Les résultats économiques donnent la perspective du payeur et de la société : productivité, nombre de séances, coûts.","s":5},{"q":"Qu'est-ce qu'un Core Outcome Set ?","o":["La liste complète de tous les résultats mesurables","Un socle minimal de résultats, à mesurer dans les études","Un questionnaire validé, en plusieurs langues","Un modèle statistique, multivarié"],"r":1,"e":"Un COS est un ensemble minimal de domaines de résultats considérés fondamentaux pour la prise de décisions cliniques et qui doivent être mesurés dans les études de recherche. Ces domaines sont jugés fondamentaux pour la prise de décision clinique.","s":5},{"q":"Quelle initiative est citée comme ressource pour les Core Outcome Sets ?","o":["COMET","COSMIN","PROSPERO","PRISMA"],"r":0,"e":"Le cours renvoie à comet-initiative.org et ichom.org pour les Core Outcome Sets ; COSMIN concerne les propriétés psychométriques.","s":5},{"q":"Quelle est la différence entre construit et instrument ?","o":["Le construit est ce qu'on mesure, l'instrument comment","Le construit est l'outil, l'instrument la théorie qui le fonde","Ce sont deux synonymes, en pratique","Le construit est toujours quantitatif"],"r":0,"e":"Le concept/construit ou domaine est ce que l'on prétend mesurer ; les méthodes et instruments définissent comment le construit est mesuré.","s":5},{"q":"Qu'évaluent les PREM ?","o":["La satisfaction ou la qualité de l'expérience","Les résultats de l'intervention sur la santé","L'amplitude de mouvement","Les coûts de la prise en charge"],"r":0,"e":"Les PREM, Patient-Reported Experience Measures, évaluent la satisfaction et la qualité de l'expérience ; les PROM évaluent la qualité de l'intervention et des résultats sur la santé.","s":5},{"q":"Lequel de ces instruments est un PROM cité dans le cours ?","o":["Le questionnaire HCAHPS, d'expérience","Le SF-36 et l'EuroQol EQ-5D","L'oxymètre de pouls, au doigt, sur 24 heures","Le grade de force, coté de 0 à 5"],"r":1,"e":"Le SF-36 et l'EuroQol EQ-5D sont donnés comme exemples de PROM ; le Hospital Consumer Assessment est un exemple de PREM. L'HCAHPS est un exemple de PREM.","s":5},{"q":"À quelle catégorie appartient le SF-36 parmi les types d'instruments ?","o":["Générique, de qualité de vie","Spécifique d'une région du corps","Spécifique de signes et symptômes","Spécifique d'une population, ciblée"],"r":0,"e":"Le SF-36 est cité comme instrument générique de qualité de vie.","s":5},{"q":"À quelle catégorie appartient le McGill Pain Questionnaire ?","o":["Générique","Spécifique de signes et symptômes","Spécifique de population","Spécifique de région du corps"],"r":1,"e":"Le McGill Pain Questionnaire est un instrument spécifique de signes et symptômes.","s":5},{"q":"À quelle catégorie appartient le Cincinnati Knee Rating System ?","o":["Spécifique d'une région du corps","Générique","Spécifique d'une population","Spécifique d'un domaine"],"r":0,"e":"Le Cincinnati Knee Rating System est spécifique d'une région du corps.","s":5},{"q":"Quelles sont les trois qualités fondamentales d'un instrument de mesure ?","o":["Rapidité, coût et simplicité","Validité, fiabilité et sensibilité au changement","Généralisabilité, précision et reproductibilité","Traduction, adaptation et publication"],"r":1,"e":"Un instrument doit être valide (il mesure ce qu'il est censé mesurer), fiable (information cohérente) et sensible au changement (il détecte des changements au fil du temps).","s":5},{"q":"Que signifie COSMIN ?","o":["COnsensus based Standards for the selection of health Measurement INstruments","COmparative Overview of Standardized Measurement INstruments","COre Outcome Standards for Measurement INstruments in rehabilitation","COnsortium for Standardized Outcomes in Medicine and health INstruments"],"r":0,"e":"COSMIN signifie COnsensus based Standards for the selection of health Measurement INstruments.","s":5},{"q":"Comment définit-on la validité d'un instrument ?","o":["La cohérence de l'information produite","Le fait de mesurer ce qu'il prétend mesurer","La capacité à détecter des changements","La facilité de calcul du score total, à la main"],"r":1,"e":"La validité est la propriété de mesurer ce que l'on prétend qu'il mesure : la qualité d'un instrument quand il mesure bien la réalité pour laquelle il a été construit.","s":5},{"q":"Que vérifie la validité de contenu ?","o":["Si les items couvrent bien le construit à mesurer","Si l'instrument confirme une théorie établie","Si les scores restent stables dans le temps","Si l'instrument détecte bien le changement"],"r":0,"e":"La validité de contenu cherche à répondre si le contenu et les items d'un instrument reflètent de façon adéquate le construit à mesurer, incluant les aspects les plus adéquats, importants et pertinents. Les items doivent inclure les aspects les plus pertinents.","s":5},{"q":"Que concerne la validité de construit ?","o":["La traduction de l'instrument, dans une autre langue","La validation d'une théorie, par des hypothèses","La comparaison entre deux observateurs","Le temps d'application de l'outil"],"r":1,"e":"La validité de construit se réfère à la validation d'une théorie : il y a confirmation d'hypothèses et on vérifie si les scores de l'instrument sont reliés les uns aux autres. On vérifie aussi les relations entre les scores.","s":5},{"q":"Comment définit-on la fiabilité ?","o":["La capacité à mesurer, vraiment, ce qui doit l'être","La cohérence des réponses, quel que soit le moment","La capacité à détecter un changement minimal","La pertinence culturelle de l'instrument"],"r":1,"e":"La fiabilité concerne la précision ou la cohérence de l'information : elle évalue dans quelle mesure une procédure produit la même réponse indépendamment de la façon et du moment où elle est appliquée. C'est la précision ou la cohérence de l'information, quelle que soit la façon d'appliquer la mesure.","s":5},{"q":"Quel indicateur mesure la cohérence interne ?","o":["Le coefficient kappa","L'alpha de Cronbach","Le coefficient intraclasse","La valeur p, au seuil de 5 %"],"r":1,"e":"L'alpha de Cronbach est l'indicateur le plus utilisé pour la cohérence interne ; ses valeurs varient entre 0 et 0,95.","s":5},{"q":"Quel seuil d'alpha de Cronbach indique une bonne consistance interne ?","o":["Égal ou supérieur à 0,3","Égal ou supérieur à 0,5","Égal ou supérieur à 0,7","Égal ou supérieur à 0,95"],"r":2,"e":"Le cours retient une consistance interne égale ou supérieure à 0,7 ; les valeurs de l'alpha varient entre 0 et 0,95.","s":5},{"q":"Comment évalue-t-on la fiabilité test-retest ?","o":["On remesure la même population plus tard, et on compare","On compare deux évaluateurs différents, le même jour","On corrèle les items entre eux, à un instant","On mesure l'erreur de score, en valeur absolue"],"r":0,"e":"La fiabilité test-retest, ou stabilité intertemporelle, s'évalue par l'application de la mesure à la même population à différents moments et par comparaison des scores obtenus.","s":5},{"q":"Comment choisir l'intervalle entre test et retest ?","o":["Le plus court possible, le même jour","Ni trop court, ni trop long pour un changement réel","Au moins un an, pour la stabilité","L'intervalle n'a aucune importance, quelle que soit la mesure"],"r":1,"e":"L'intervalle doit être suffisant pour que les participants ne répliquent pas les réponses originales, mais pas si long qu'il permette la survenue d'un changement réel. Il doit éviter que les participants se souviennent de leurs réponses.","s":5},{"q":"Qu'est-ce que l'erreur de mesure ?","o":["Une faute de calcul du score","Une erreur de score non due à un vrai changement","Un biais de sélection, à l'inclusion des participants","Une différence entre deux populations"],"r":1,"e":"L'erreur de mesure est l'erreur de score de l'instrument qui ne peut pas être attribuée à des changements du construit mesuré. Le changement non réel est celui du construit mesuré.","s":5},{"q":"Comment définit-on la réactivité ?","o":["La rapidité d'application de l'instrument","La capacité à détecter un changement important","La cohérence entre les items","La pertinence des items, pour le patient et le clinicien"],"r":1,"e":"La réactivité est la capacité à détecter des changements au fil du temps définis comme minimaux et considérés importants ; elle comprend pouvoir de réponse, interprétabilité, sensibilité et spécificité. Ce changement est défini comme minimal et important, au fil du temps.","s":5},{"q":"Qu'est-ce que l'interprétabilité d'un instrument ?","o":["Le sens qualitatif qu'on peut donner aux scores","La facilité de traduction, dans une autre langue","La rapidité de passation, en minutes","La corrélation entre les items"],"r":0,"e":"L'interprétabilité, ou pouvoir interprétatif, est le degré selon lequel on peut attribuer une signification qualitative facilement compréhensible aux valeurs quantitatives obtenues par l'instrument.","s":5},{"q":"Qu'est-ce que la sensibilité d'un test ?","o":["Identifier correctement les personnes malades","Identifier correctement les personnes saines","La reproductibilité du test, d'un jour à l'autre","La rapidité du test, au lit du patient, en urgence"],"r":0,"e":"La sensibilité est la capacité du test à identifier correctement les individus qui présentent une maladie déterminée ou un autre résultat (résultat +). Elle repère les résultats positifs.","s":5},{"q":"Quel est l'ordre d'importance des critères psychométriques selon le cours ?","o":["Contenu, puis consistance interne, puis le reste","Réactivité, puis fiabilité, puis validité","Consistance interne, puis réactivité, puis validité de contenu","Tous les critères ont la même importance"],"r":0,"e":"L'ordre d'importance est : 1. validité — validité de contenu ; 2. fiabilité — consistance interne ; 3. autres validités, fiabilités et la réactivité. La validité de contenu vient d'abord ; viennent ensuite les autres validités, fiabilités et la réactivité.","s":5},{"q":"Quelle référence encadre l'adaptation transculturelle d'instruments ?","o":["Beaton et al., 2000","Domholdt, 2000","Rothstein, 1995","Cochrane, 1979"],"r":0,"e":"Le processus d'adaptation transculturelle suit Beaton et al. (2000), qui garantit l'équivalence conceptuelle et sémantique avec l'original.","s":5},{"q":"Quelle exigence pèse sur les rétrotraducteurs (étape 3) ?","o":["Être des professionnels de santé expérimentés","Être aveugles et étrangers au domaine de la santé","Être les mêmes traducteurs que ceux de la première étape","Être au moins quatre, en binômes"],"r":1,"e":"Les rétrotraducteurs doivent être de même langue maternelle que celle de l'instrument original, être « aveugles » et de préférence appartenir à un autre domaine de connaissance que celui de la santé. Ils doivent avoir la même langue maternelle que l'instrument original.","s":5},{"q":"Combien de participants le pré-test doit-il idéalement compter ?","o":["10 à 15","30 à 40","100 à 150","Au moins 300"],"r":1,"e":"Le pré-test devra idéalement compter 30 à 40 participants volontaires afin d'établir la validation de contenu de l'échelle.","s":5},{"q":"Parmi les résultats cliniques, le cours cite :","o":["L'amplitude articulaire, le tonus, la force","La qualité de vie, générique et spécifique","Le nombre de séances, sur une année","La satisfaction du patient, après la séance"],"r":0,"e":"Les résultats humanistiques relèvent de la perspective des patients et des proches ; les résultats économiques de celle du payeur et de la société.","s":5},{"q":"Un construit, en méthodologie de la mesure, désigne :","o":["L'instrument utilisé, et sa version","Ce que l'on prétend mesurer","Le résultat obtenu, chiffré","La population cible de l'étude"],"r":1,"e":"L'instrument est le moyen par lequel le construit est mesuré. Confondre les deux revient à prendre le thermomètre pour la température.","s":5},{"q":"Les PREM évaluent :","o":["Les résultats sur la santé","La satisfaction et l'expérience vécue","Les coûts de la prise en charge","Les amplitudes articulaires, au goniomètre"],"r":1,"e":"Les PROM évaluent la satisfaction et la qualité de l'intervention ainsi que ses résultats sur la santé ; le SF-36 et l'EuroQol EQ-5D en sont des exemples. Ils portent sur la qualité de l'expérience des soins.","s":5},{"q":"Le McGill Pain Questionnaire est cité comme instrument :","o":["Générique","Spécifique d'une condition","Spécifique de signes et symptômes","Spécifique d'une région du corps"],"r":2,"e":"Le SF-36 est l'exemple d'instrument générique. Les six types recensés couvrent aussi les instruments spécifiques d'une population et d'un domaine.","s":5},{"q":"Les trois critères psychométriques fondamentaux sont :","o":["Validité, fiabilité et réactivité","Sensibilité, spécificité et précision","Fidélité, exactitude et reproductibilité","Pertinence, faisabilité et coût"],"r":0,"e":"COSMIN en est la référence méthodologique. Par ordre d'importance : validité de contenu, consistance interne, puis les autres validités, fiabilités et la réactivité.","s":5},{"q":"La réactivité d'un instrument désigne sa capacité à :","o":["Mesurer ce qu'il est censé mesurer","Fournir une information cohérente","Détecter des changements au fil du temps","Être compris par le patient"],"r":2,"e":"C'est une qualité décisive en rééducation : un instrument valide et fiable mais peu réactif ne permettra pas de suivre les progrès d'un patient.","s":5},{"q":"L'alpha de Cronbach est considéré comme satisfaisant à partir de :","o":["0,5","0,6","0,7","0,9"],"r":2,"e":"Ses valeurs s'échelonnent de 0 à 0,95. Il mesure la cohérence interne, c'est-à-dire la concordance entre les items censés évaluer le même construit.","s":5},{"q":"La fiabilité test-retest évalue :","o":["La concordance entre observateurs","La stabilité des mesures dans le temps","La cohérence entre les items","L'erreur de mesure absolue"],"r":1,"e":"Les autres formes de fiabilité sont la cohérence interne, la fiabilité inter et intra-observateurs, et l'erreur de mesure.","s":5},{"q":"La spécificité d'un test se définit comme sa capacité à :","o":["Identifier correctement les individus qui présentent la maladie","Identifier correctement ceux qui ne la présentent pas","Détecter les changements dans le temps","Mesurer plusieurs construits"],"r":1,"e":"La sensibilité est l'inverse : identifier correctement ceux qui ont la maladie. Un test très sensible sert à écarter, un test très spécifique à confirmer.","s":5},{"q":"L'adaptation transculturelle selon Beaton et al. (2000) comporte :","o":["4 étapes","6 étapes","8 étapes","10 étapes"],"r":1,"e":"Traduction par deux traducteurs, synthèse, rétrotraduction par deux autres, comité d'experts, pré-test sur 30 à 40 participants, puis envoi du matériel aux auteurs originaux.","s":5},{"q":"Le pré-test de l'adaptation transculturelle porte sur :","o":["10 participants","20 participants","30 à 40 participants","100 participants"],"r":2,"e":"Il vise à vérifier la compréhension effective des items dans la langue cible, avant toute étude psychométrique de validation.","s":5},{"q":"Les trois critères obligatoires de l'adaptation transculturelle sont :","o":["Équivalences conceptuelle et sémantique, psychométrie","Traduction, rétrotraduction, pré-test, comité, publication","Validité, fiabilité et réactivité de l'outil","Sensibilité, spécificité et précision"],"r":0,"e":"Le cours rappelle en outre la nécessité d'obtenir l'autorisation d'utilisation auprès des auteurs de l'instrument original.","s":5},{"q":"Les Core Outcome Sets correspondent à :","o":["L'ensemble des instruments validés d'un domaine","Un socle minimal de résultats, à mesurer dans les études","Les recommandations cliniques, graduées selon le niveau de preuve","Les critères d'inclusion d'une revue"],"r":1,"e":"Les initiatives COMET et ICHOM les développent. Leur intérêt est de rendre les études comparables entre elles en harmonisant ce qui est mesuré. Ces domaines de résultats sont jugés fondamentaux.","s":5},{"q":"La citation de Jules Rothstein (1995) rapportée par le cours affirme que la kinésithérapie :","o":["Est une science exacte, entièrement mesurable","Reste un art, mais sans mesure ne serait qu'un art","Doit renoncer à la mesure, pour rester un art humain","Est identique à la médecine, dans ses méthodes"],"r":1,"e":"La formule articule les deux versants : la mesure ne supprime pas la dimension d'art, elle l'empêche de rester sans fondement vérifiable.","s":5},{"q":"L'évaluation, distinguée de la mesure, se définit comme :","o":["La quantification de caractéristiques précises","Un processus de recueil et d'interprétation","Le calcul d'un score, total ou partiel","La comparaison à une norme, établie sur une large population"],"r":1,"e":"La mesure est un acte technique ; l'évaluation, un processus de raisonnement qui englobe le choix de ce qui est mesuré et l'interprétation du résultat. L'information clinique est subjective et objective ; elle est sélectionnée, recueillie, analysée et interprétée.","s":5},{"q":"Le SF-36 est cité comme exemple d'instrument :","o":["Générique, pour la qualité de vie","Spécifique, d'une région du corps","Spécifique, de signes et symptômes","Spécifique, d'une population"],"r":0,"e":"Il figure également parmi les exemples de PROM, aux côtés de l'EuroQol EQ-5D, ce qui illustre le recoupement entre les deux classifications.","s":5},{"q":"Les modèles conceptuels servant à identifier les résultats à mesurer incluent notamment :","o":["La CIF","Le modèle biomédical","La pyramide de l'évidence","GRADE"],"r":0,"e":"S'y ajoutent les modèles endpoint, spécifiques par pathologie, et les Core Outcome Sets développés par COMET et ICHOM.","s":5},{"q":"L'erreur de mesure est classée dans le cours parmi :","o":["Les types de validité","Les types de fiabilité","Les types de réactivité","Les critères de sensibilité"],"r":1,"e":"Elle rejoint la cohérence interne, le test-retest et la fiabilité inter et intra-observateurs, qui explorent tous la constance de l'information produite.","s":5},{"q":"Un instrument spécifique d'une population se distingue d'un instrument spécifique d'une condition parce qu'il cible :","o":["Un groupe défini par l'âge ou le statut","Une région anatomique, comme le genou ou l'épaule","Un symptôme isolé, comme la douleur","Un domaine conceptuel, comme la fonction"],"r":0,"e":"Les six types recensés couvrent les instruments génériques, spécifiques d'une condition, d'une population, de signes et symptômes, d'une région du corps et d'un domaine. Il ne cible pas une pathologie.","s":5},{"q":"Selon l'ordre d'importance donné par le cours, le premier critère psychométrique à considérer est :","o":["La consistance interne","La validité de contenu","La réactivité","La fiabilité test-retest"],"r":1,"e":"Un instrument qui ne couvre pas correctement le construit ne peut être rattrapé par aucune autre qualité : la validité de contenu conditionne tout le reste.","s":5},{"q":"Que représente la partie visible de l'iceberg dans le modèle iceberg en santé ?","o":["L'évidence présentée, c'est-à-dire la pyramide","Les biais de publication, cachés","L'expertise du clinicien, implicite","Les préférences du patient, souvent non exprimées"],"r":0,"e":"La partie visible représente l'évidence clinique présentée — la pyramide de l'évidence ; la partie immergée correspond aux aspects cachés de l'évidence clinique. La partie immergée correspond aux aspects cachés de l'évidence clinique.","s":6},{"q":"Que souligne le modèle iceberg ?","o":["Que la PBE suffit, à elle seule","Qu'il existe d'autres données utiles au-delà de la PBE","Que la pyramide doit être abandonnée, au profit de l'avis","Que seule la méta-analyse compte, au sommet de la pyramide"],"r":1,"e":"Le modèle souligne l'importance d'une approche plus approfondie des données : au-delà de la PBE, il existe plus d'informations pertinentes pour comprendre les résultats en santé. Il souligne l'importance d'une approche plus approfondie des données.","s":6},{"q":"Que se passe-t-il à mesure qu'on monte dans la pyramide de l'évidence ?","o":["Plus de littérature, mais moins pertinente","Moins de littérature, mais plus pertinente","Plus de littérature, et plus pertinente pour la clinique","Aucun changement, ni en quantité ni en pertinence"],"r":1,"e":"En montant dans la pyramide, on a moins de littérature disponible mais plus de littérature pertinente pour la pratique clinique.","s":6},{"q":"Comment Sackett (2000) définit-il la pratique fondée sur l'évidence ?","o":["L'application stricte, des seuls essais randomisés","Évidence, expertise et valeurs du patient, réunies","La consultation, systématique, des guidelines","La recherche de consensus entre experts"],"r":1,"e":"Selon Sackett (2000), la PBE est l'intégration de la meilleure évidence disponible avec l'expertise clinique et avec les valeurs du patient. L'évidence est la meilleure disponible ; l'expertise est clinique.","s":6},{"q":"Quelles sont les cinq étapes de la PBE ?","o":["Question, recherche, évaluation, application, outcomes","Lire, résumer, appliquer, publier, réviser","Diagnostiquer, traiter, évaluer, adapter, conclure","Chercher, sélectionner, extraire, analyser, conclure"],"r":0,"e":"Les cinq étapes sont : poser une question, trouver la meilleure évidence, évaluer l'évidence, appliquer l'information et évaluer les outcomes. On pose une question, on trouve la meilleure évidence, on l'évalue, on applique l'information puis on évalue les outcomes.","s":6},{"q":"Qui peut chercher l'évidence selon le cours ?","o":["Uniquement le professionnel de santé","Le professionnel, et le patient s'il le souhaite","Uniquement un documentaliste, formé","Uniquement un chercheur universitaire, spécialisé"],"r":1,"e":"Le professionnel fait une recherche, mais le patient peut aussi le faire s'il le souhaite, en étant orienté par le professionnel. Le patient est alors orienté par le professionnel.","s":6},{"q":"Comment se prend la décision à l'étape « appliquer l'information » ?","o":["Le professionnel décide seul, selon les guidelines","Ensemble, selon les valeurs et préférences du patient","Le patient décide seul, sans information","Elle suit le niveau de preuve, automatiquement"],"r":1,"e":"Le patient discute avec le professionnel de la meilleure option, le professionnel informe sur les risques et bénéfices, et ensemble ils décident selon les valeurs et préférences du patient. Le professionnel informe sur les risques et les bénéfices.","s":6},{"q":"Quel principe justifie la hiérarchie de l'évidence ?","o":["L'évidence n'est pas toute égale ni valide","Toutes les études se valent","Seuls les experts jugent la qualité","La littérature récente est toujours meilleure"],"r":0,"e":"L'évidence n'est pas toute égale ni valide : la hiérarchie de l'évidence guide la décision clinique en graduant la force de l'évidence.","s":6},{"q":"Pourquoi l'évidence seule ne suffit-elle jamais ?","o":["Parce qu'elle est toujours fausse","Parce qu'il faut l'expérience pour cerner chaque patient","Parce qu'elle est trop coûteuse à obtenir","Parce qu'elle est difficile à lire et à comprendre en anglais"],"r":1,"e":"L'évidence à elle seule ne sera jamais suffisante : les professionnels doivent utiliser leur expérience pour identifier rapidement la situation clinique de chaque patient. L'expérience permet d'identifier rapidement la situation clinique.","s":6},{"q":"Quel est le principe central de la pratique informée par l'évidence ?","o":["S'orienter grâce à l'évidence, sans en dépendre","Suivre strictement les guidelines","Ignorer la recherche scientifique, au profit du terrain","Ne se fier qu'à l'expérience clinique"],"r":0,"e":"La PIE utilise l'évidence scientifique comme une orientation pour la prise de décisions, mais sans en dépendre exclusivement. L'évidence oriente la prise de décision, sans en être l'unique source.","s":6},{"q":"Que reconnaît la pratique informée par l'évidence ?","o":["Que la recherche est toujours applicable","Qu'on ne peut pas toujours suivre les directives","Que les guidelines sont inutiles, en pratique","Que l'expérience clinique doit primer systématiquement"],"r":1,"e":"La PIE reconnaît qu'il n'est pas toujours possible ou nécessaire de suivre strictement les directives de la PBE, en particulier là où la recherche est limitée, non concluante ou non directement applicable. C'est le cas quand la recherche est limitée, non concluante ou non applicable ; il s'agit des directives de la PBE.","s":6},{"q":"Qu'est-ce que la PIE valorise ?","o":["La rigueur statistique","L'applicabilité et l'adaptabilité","L'uniformité des protocoles","La quantité de publications"],"r":1,"e":"La PIE valorise l'applicabilité et l'adaptabilité, reconnaissant que la science ne fournit pas toujours de réponses toutes faites pour tous les contextes.","s":6},{"q":"Comment l'APTA définit-elle la pratique kinésithérapique fondée sur les preuves ?","o":["Une application mécanique des données probantes","Une décision clinique ouverte et réfléchie","Un protocole de soins standardisé, national","Une recherche bibliographique avant chaque séance"],"r":1,"e":"L'EBPP est une « prise de décision clinique ouverte et réfléchie » intégrant les meilleures données disponibles avec le jugement clinique, les préférences et valeurs du patient, et tenant compte du contexte social plus large. Elle intègre les meilleures données, le jugement clinique, les préférences du patient et le contexte social.","s":6},{"q":"Quel est l'objectif de l'EBPP selon l'APTA ?","o":["Réduire les coûts de santé publique","Optimiser les résultats et la qualité de vie","Uniformiser les pratiques professionnelles, partout","Augmenter le nombre de publications"],"r":1,"e":"L'EBPP vise à optimiser les résultats et la qualité de vie du patient. Il s'agit des résultats et de la qualité de vie du patient.","s":6},{"q":"Que déclare la WCPT en 2001 concernant les décisions en kinésithérapie ?","o":["Sur l'expérience du praticien, avant tout","Sur des études rigoureuses, reconnues par la communauté","Sur les protocoles de l'institution","Sur la seule validation par le patient, en fin de séance"],"r":1,"e":"Selon la WCPT (2001), les décisions en kinésithérapie doivent être fondées sur des études présentant des résultats étayés par des méthodologies rigoureuses et dont l'évidence est acceptée comme valide par la communauté scientifique. L'évidence doit être acceptée comme valide par la communauté scientifique.","s":6},{"q":"À quoi correspond le Type I d'évidence selon Cochrane (2004) ?","o":["Une revue systématique ou un essai randomisé bien conçu","Un essai randomisé de taille adéquate, mené en multicentrique","Une étude de cohorte, prospective et contrôlée","Une opinion d'expert, issue d'un consensus"],"r":0,"e":"Le Type I correspond à une évidence forte provenant d'au moins une revue systématique ou d'un ECR bien conçu. Il s'agit d'une évidence forte ; au moins une étude de ce type suffit.","s":6},{"q":"À quoi correspond le Type III d'évidence ?","o":["À une méta-analyse d'essais","À des études non randomisées bien conçues","À des opinions d'autorités respectées","À un essai randomisé de grande taille, multicentrique"],"r":1,"e":"Le Type III correspond à l'évidence provenant d'études bien conçues mais sans randomisation : études de cohorte, cas-témoins et transversales. Ce sont les études de cohorte, cas-témoins et transversales.","s":6},{"q":"À quoi correspond le Type V d'évidence ?","o":["Aux études non expérimentales, de plusieurs centres","Aux opinions d'autorités, aux rapports d'experts","Aux revues systématiques, avec méta-analyse","Aux essais randomisés, de petite taille"],"r":1,"e":"Le Type V regroupe les opinions d'autorités respectées fondées sur l'évidence clinique, les études descriptives ou les rapports de comités d'« experts ». Les études descriptives en font aussi partie.","s":6},{"q":"Comment le cours décrit-il, avec humour, le Type VI d'évidence ?","o":["« Un collègue l'a essayé »","« Quelqu'un me l'a dit une fois »","« C'est écrit dans un vieux livre »","« C'est logique, tout simplement »"],"r":1,"e":"Le Type VI, dernier niveau de la classification Cochrane 2004 présentée, est formulé « Quelqu'un me l'a dit une fois ».","s":6},{"q":"Quelle est la différence entre les types IV et V d'évidence ?","o":["Le IV vient d'études multicentriques, le V d'opinions","Le type IV est plus faible que le type V, qui regroupe les essais","Le type IV concerne les essais randomisés","Il n'y a aucune différence entre les deux"],"r":0,"e":"Le type IV provient d'études non expérimentales bien conçues, de plus d'un centre ou groupe de recherche ; le type V regroupe opinions d'autorités, études descriptives et rapports de comités d'experts. Le type IV provient d'études non expérimentales bien conçues ; le type V regroupe opinions d'autorités et études descriptives.","s":6},{"q":"Que signifie un grade de recommandation A ?","o":["Une faible évidence, à confirmer","Une évidence suffisante, de niveau modéré","Une évidence forte, favorable","Des études incohérentes, discordantes"],"r":2,"e":"Le grade A correspond à une évidence forte qui soutient la recommandation que l'intervention doit être considérée. L'intervention doit alors être considérée.","s":6},{"q":"Que signifie un grade de recommandation D ?","o":["Évidence forte contre l'intervention","Études incohérentes et non concluantes","Faible évidence mais recommandation possible","Évidence suffisante"],"r":1,"e":"Le grade D correspond à des études incohérentes et non concluantes.","s":6},{"q":"Que signifie un grade de recommandation C ?","o":["Une faible évidence, pour ou contre l'intervention","Une évidence forte, de grade élevé","Une absence totale d'études publiées","Une contre-indication formelle, inscrite dans les guidelines"],"r":0,"e":"Le grade C correspond à une faible évidence soutenant l'inclusion ou l'exclusion de l'intervention, mais des recommandations peuvent être faites dans d'autres domaines. Des recommandations restent possibles dans d'autres domaines.","s":6},{"q":"Selon la classification JAMA (2000), sur quoi repose le niveau 1 ?","o":["Des rapports de cas, isolés","Des études prospectives non randomisées","Des essais randomisés ou leur méta-analyse","L'opinion de spécialistes, réunis en conférence de consensus"],"r":2,"e":"Le niveau 1 du JAMA repose sur des essais cliniques randomisés ou une méta-analyse d'essais cliniques : action fortement recommandée. L'action est alors fortement recommandée.","s":6},{"q":"Selon la classification JAMA, que conclut-on d'un niveau 3 ?","o":["Action fortement recommandée","Action recommandée","Action peu recommandée","Action contre-indiquée"],"r":2,"e":"Le niveau 3 repose sur des rapports de cas ou l'opinion de spécialistes : l'action est peu recommandée.","s":6},{"q":"Sur quoi repose le niveau 2 de la classification JAMA ?","o":["Des essais randomisés, en double aveugle","Des études prospectives non randomisées","Des méta-analyses d'essais","Des séries de cas cliniques"],"r":1,"e":"Le niveau 2 repose sur des études prospectives non randomisées : action recommandée.","s":6},{"q":"Quel outil est présenté comme le plus adopté pour classer la qualité de l'évidence ?","o":["GRADE","PRISMA","AMSTAR","CONSORT"],"r":0,"e":"GRADE est l'outil le plus adopté pour classer la qualité de l'évidence et formuler les recommandations.","s":6},{"q":"Quelle priorité de recherche arrive en tête chez les kinésithérapeutes portugais et les patients ?","o":["Le coût-efficacité","Le développement professionnel","La qualité","La prestation de services"],"r":0,"e":"Parmi les 10 priorités les plus consensuelles figurent, dans l'ordre présenté : coût-efficacité, prestation de services et éducation, développement professionnel, qualité.","s":6},{"q":"Quel épisode historique a conduit Archie Cochrane à réaliser ce que le cours décrit comme le premier essai clinique ?","o":["Une épidémie de grippe à l'hôpital","Sa captivité, où il compara vitamines D et C","Une étude sur l'aspirine après un infarctus du myocarde","Une enquête sur la tuberculose, en Écosse"],"r":1,"e":"Prisonnier de guerre, il a observé des œdèmes des membres inférieurs qu'il attribuait à une carence vitaminique, et a comparé deux groupes de prisonniers, l'un recevant de la vitamine D, l'autre de la vitamine C. Les prisonniers présentaient des œdèmes des membres inférieurs.","s":6},{"q":"Quel est l'objectif de la recherche dans la pratique clinique du kinésithérapeute selon le cours ?","o":["Remplacer le raisonnement clinique","Aider à choisir la meilleure évidence pour décider","Justifier après coup les traitements choisis, au dossier","Satisfaire aux obligations universitaires"],"r":1,"e":"Il s'agit de rechercher dans la pratique clinique comme adjuvant à l'intervention du kinésithérapeute, et de sélectionner la meilleure évidence clinique pour collaborer à la planification et à la prise de décisions. Elle sert d'adjuvant à l'intervention.","s":6},{"q":"Dans le modèle iceberg en santé, la partie visible correspond :","o":["Aux aspects cachés de l'évidence","À l'évidence présentée, c'est-à-dire la pyramide","Aux préférences du patient, implicites","Au coût des interventions, pour la société"],"r":1,"e":"Le modèle rappelle qu'au-delà de la PBE, il existe davantage d'informations pertinentes pour comprendre les résultats en santé.","s":6},{"q":"En montant dans la pyramide de l'évidence :","o":["La littérature augmente, sa pertinence diminue","La littérature diminue, sa pertinence augmente","Les deux augmentent, quantité et pertinence","Les deux diminuent, quantité comme pertinence clinique"],"r":1,"e":"Les revues systématiques et méta-analyses sont rares mais directement exploitables ; les études primaires sont nombreuses mais exigent un travail d'interprétation.","s":6},{"q":"La définition de la PBE par Sackett (2000) intègre :","o":["L'évidence, l'expertise et les valeurs du patient","Les preuves et les recommandations officielles","L'expérience du praticien, uniquement","Le rapport coût-efficacité de l'intervention"],"r":0,"e":"Ces trois composantes sont indissociables : retirer l'une d'elles fait sortir du cadre de la pratique fondée sur l'évidence.","s":6},{"q":"La deuxième des cinq étapes de la PBE consiste à :","o":["Poser une question","Trouver la meilleure évidence","Évaluer l'évidence","Appliquer l'information"],"r":1,"e":"La séquence complète : poser une question, trouver la meilleure évidence, l'évaluer, appliquer l'information, puis évaluer les outcomes.","s":6},{"q":"La cinquième étape de la PBE consiste à :","o":["Publier les résultats","Évaluer les outcomes","Rechercher de nouvelles preuves","Former les collègues"],"r":1,"e":"Cette dernière étape referme la boucle : sans évaluation du résultat obtenu chez ce patient, l'application de la preuve reste un pari non vérifié.","s":6},{"q":"Le deuxième principe de la PBE énonce que :","o":["Toute évidence se vaut, quelle qu'elle soit","L'évidence seule ne suffit jamais, sans l'expérience","L'expérience prime toujours sur les preuves","Les préférences du patient restent secondaires, après tout"],"r":1,"e":"Le premier principe pose que l'évidence n'est ni toute égale ni toute valide, d'où la hiérarchie ; le troisième impose d'appliquer selon le rapport risques/bénéfices pour chaque patient. L'expérience du professionnel identifie la situation clinique.","s":6},{"q":"La pratique informée par l'évidence (PIE) se distingue en ce qu'elle :","o":["Rejette les preuves scientifiques","Se sert de l'évidence comme guide, adapté au contexte","Suit strictement les guidelines, sans aucune adaptation","Se fonde sur l'opinion d'experts, réunis"],"r":1,"e":"Elle valorise l'applicabilité et l'adaptabilité, et reconnaît que la science, outil puissant, ne fournit pas toujours de réponses toutes faites pour tous les contextes. Elle ne dépend pas exclusivement de l'évidence et tient compte de l'expérience et des besoins du patient.","s":6},{"q":"L'EBPP défini par l'APTA est décrit comme :","o":["Une application mécanique des protocoles","Une décision ouverte, réfléchie, attentive au contexte","Un algorithme décisionnel, informatisé et validé nationalement","Une démarche exclusivement scientifique"],"r":1,"e":"L'objectif affiché est d'optimiser les résultats et la qualité de vie. La mention du contexte social élargit le cadre au-delà du colloque singulier. Elle intègre preuves, jugement clinique et préférences du patient.","s":6},{"q":"Selon la classification Cochrane (2004), le type d'évidence I correspond :","o":["À une revue systématique ou un essai randomisé solide","À un essai randomisé, de taille adéquate","À une étude de cohorte, prospective et multicentrique","À l'opinion d'experts, réunis en comité"],"r":0,"e":"Le type II correspond à un ECR bien conçu et de taille adéquate, le type III aux études bien conçues sans randomisation.","s":6},{"q":"Le type d'évidence V de la classification Cochrane regroupe :","o":["Les études non expérimentales multicentriques","Les opinions d'autorités et les rapports d'experts","Les essais randomisés de petite taille","Les revues systématiques, sans méta-analyse"],"r":1,"e":"Le type VI, dernier de l'échelle, est formulé avec humour par le cours : « quelqu'un me l'a dit une fois ». Les études descriptives en font aussi partie.","s":6},{"q":"Le type d'évidence IV correspond :","o":["Aux études non expérimentales, de plusieurs centres","Aux essais randomisés, contrôlés","Aux revues systématiques, avec ou sans méta-analyse d'essais","Aux opinions d'experts, consensuelles"],"r":0,"e":"Le caractère multicentrique renforce la crédibilité en réduisant le risque qu'un résultat tienne aux particularités d'un seul lieu. Ces études sont bien conçues.","s":6},{"q":"Le grade de recommandation B correspond à :","o":["Une évidence forte","Une évidence suffisante","Une faible évidence","Des études incohérentes et non concluantes"],"r":1,"e":"Le grade A correspond à une évidence forte, le C à une faible évidence, le D à des études incohérentes et non concluantes.","s":6},{"q":"Selon la classification JAMA (2000), le niveau 2 correspond :","o":["À un ECR ou une méta-analyse, action fortement recommandée","À des études prospectives non randomisées, action recommandée","À des rapports de cas, action peu recommandée","À l'opinion de spécialistes"],"r":1,"e":"Le niveau 1 réunit ECR et méta-analyses avec une action fortement recommandée ; le niveau 3 les rapports de cas et opinions de spécialistes, peu recommandés.","s":6},{"q":"L'exemple du cours sur le choix entre comprimés et injections de morphine en post-opératoire illustre :","o":["Une question de coût, pour l'hôpital et le patient","La pratique fondée sur l'évidence, en situation","Un problème de diagnostic, différentiel et précoce","Une question éthique, de consentement"],"r":1,"e":"Il met en scène les trois composantes : ce que disent les données, ce que sait le clinicien de cette situation, et ce que le patient préfère. C'est l'application concrète de la PBE à une décision de traitement.","s":6},{"q":"La pyramide de l'évidence a pour fonction :","o":["De classer les patients selon leur gravité clinique","De hiérarchiser l'évidence disponible","De remplacer le jugement clinique","De mesurer les résultats obtenus"],"r":1,"e":"Elle ordonne les sources selon leur capacité à limiter les biais, sans pour autant dispenser d'évaluer la qualité de chaque étude prise isolément. Elle sert de ligne directrice.","s":6},{"q":"Le premier principe de la PBE affirme que :","o":["Toutes les preuves ont la même valeur, quel que soit le design","L'évidence n'est ni toute égale ni toute valide","Les preuves suffisent à décider, seules","Seules les méta-analyses comptent"],"r":1,"e":"C'est ce qui justifie l'existence même de la pyramide et des outils d'évaluation du risque de biais comme GRADE. D'où la nécessité d'une hiérarchie.","s":6},{"q":"La pratique informée par l'évidence reconnaît explicitement que la science :","o":["Fournit toujours des réponses applicables","Ne fournit pas toujours de réponse toute faite","Doit être écartée en clinique, au profit de l'expérience","Se limite aux essais randomisés"],"r":1,"e":"Cette reconnaissance n'est pas un relativisme : elle justifie l'adaptation au contexte là où les données manquent ou ne couvrent pas la situation. C'est un outil puissant, mais pas pour tous les contextes.","s":6},{"q":"Le troisième principe de la PBE impose d'appliquer l'évidence :","o":["De la même façon pour tous les patients","Selon les risques et bénéfices de chacun","Seulement si elle est de grade A","Après l'accord de toute l'équipe"],"r":1,"e":"Une même intervention peut être justifiée chez l'un et déraisonnable chez l'autre, selon les comorbidités, l'âge ou les priorités de la personne.","s":6},{"q":"Le grade de recommandation D correspond à :","o":["Une évidence forte","Une évidence suffisante","Une faible évidence","Des études incohérentes"],"r":3,"e":"Il ne signifie pas que l'intervention est inefficace, mais que l'état des données ne permet pas de trancher — ce qui appelle prudence et réévaluation. Les études sont incohérentes et non concluantes.","s":6},{"q":"Selon JAMA (2000), le niveau 3 regroupe :","o":["Les essais randomisés, action fortement recommandée","Les études prospectives non randomisées, action recommandée","Les cas ou l'avis de spécialistes, action peu recommandée","Les méta-analyses, action fortement recommandée"],"r":2,"e":"Ces sources gardent une utilité pour les situations rares, où aucune étude de niveau supérieur n'existe ni ne pourra raisonnablement exister.","s":6},{"q":"Comment le cours définit-il la statistique ?","o":["Le recueil et l'analyse de données, pour inférer","La description chiffrée d'une population","Le calcul des probabilités, en théorie","La représentation graphique des données, en courbes"],"r":0,"e":"La statistique est la science du recueil et de l'analyse des données, dans le but d'utiliser les probabilités pour inférer d'un échantillon à la population et prédire l'évolution future d'un phénomène. On infère de l'échantillon à la population et on prédit l'évolution d'un phénomène.","s":7},{"q":"Qu'est-ce que la biostatistique ?","o":["L'étude des populations animales","La statistique appliquée à la biologie et à la santé","La biologie quantitative, en laboratoire de recherche","L'analyse des seuls essais cliniques"],"r":1,"e":"La biostatistique correspond aux statistiques appliquées aux phénomènes biologiques et liés à la santé.","s":7},{"q":"Lequel de ces éléments N'EST PAS un objectif de l'échantillonnage ?","o":["Un coût moindre, pour l'étude","Un travail de terrain réduit","Une meilleure précision","L'étude de toute la population"],"r":3,"e":"Les objectifs de l'échantillonnage sont un coût moindre, un travail de terrain réduit, une meilleure précision/validité et des méthodes optimisées. La validité est aussi meilleure ; étudier toute la population est justement ce que l'échantillon évite.","s":7},{"q":"Qu'est-ce qu'un paramètre en statistique ?","o":["Une caractéristique de la population, fixe et inconnue","Une valeur calculée sur l'échantillon, puis généralisée","Une fonction de l'échantillon, aléatoire","La valeur observée d'un individu, isolé"],"r":0,"e":"Le paramètre est la caractéristique numérique d'une population, fixe et inconnue : µ, σ², σ, p. Il est numérique : µ, σ², σ, p.","s":7},{"q":"Qu'est-ce qu'un estimateur ?","o":["Un paramètre de la population, fixe et inconnu","Une fonction de l'échantillon, donc aléatoire","La valeur numérique observée, unique","Une constante, de la population"],"r":1,"e":"L'estimateur est une fonction de l'échantillon — une variable aléatoire — notée X̄, S², S, p̂. Il se note X̄, S², S, p̂.","s":7},{"q":"Quelle est la différence entre estimateur et estimation ?","o":["L'estimateur est une fonction, l'estimation sa valeur","L'estimateur est une valeur, l'estimation une fonction","Ce sont deux synonymes, en pratique","L'estimation concerne toute la population"],"r":0,"e":"L'estimateur est une fonction de l'échantillon (variable aléatoire) ; l'estimation est l'observation numérique de cet estimateur, par exemple p̂ = 0,63. L'estimation est la valeur numérique observée de l'estimateur, par exemple p̂ = 0,63.","s":7},{"q":"Quels symboles désignent les paramètres de population ?","o":["X̄, S², S, p̂","x̄, s², s, p̂","µ, σ², σ, p","xi, yi, zi"],"r":2,"e":"Les paramètres de population sont notés µ, σ², σ et p ; les estimateurs X̄, S², S, p̂ et les estimations x̄, s², s, p̂.","s":7},{"q":"Par quoi divise-t-on pour calculer la variance d'un ÉCHANTILLON ?","o":["Par N","Par n","Par n − 1","Par n + 1"],"r":2,"e":"La variance de l'échantillon s'écrit s² = 1/(n − 1) · Σ(xᵢ − x̄)², tandis que la variance de la population divise par N.","s":7},{"q":"Quelle est la moyenne de l'échantillon 3, 7, 8, 10, 11 ?","o":["7,0","7,8","8,0","8,5"],"r":1,"e":"x̄ = (3 + 7 + 8 + 10 + 11)/5 = 7,8.","s":7},{"q":"Quelle est la variance de l'échantillon 3, 7, 8, 10, 11 ?","o":["11,76","14,70","18,37","7,80"],"r":1,"e":"s² = [(3−7,8)² + (7−7,8)² + (8−7,8)² + (10−7,8)² + (11−7,8)²]/4 = 14,70.","s":7},{"q":"Dans un échantillon de 10 individus dont 4 possèdent la caractéristique d'intérêt, quelle est la proportion estimée ?","o":["0,04","0,25","0,4","4"],"r":2,"e":"p̂ = x/n = 4/10 = 0,4.","s":7},{"q":"Quel type de variable est le nombre d'enfants ?","o":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"r":1,"e":"Le nombre d'enfants est une variable quantitative discrète : elle représente un comptage en valeurs entières.","s":7},{"q":"Quel type de variable est le poids ?","o":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"r":0,"e":"Le poids, comme la taille et l'âge, est une variable quantitative continue : c'est une mesure pouvant prendre toute valeur dans un intervalle.","s":7},{"q":"Quel type de variable est le groupe sanguin ?","o":["Quantitative discrète","Qualitative nominale","Qualitative ordinale","Quantitative continue"],"r":1,"e":"Le groupe sanguin, comme le sexe, est une variable qualitative nominale : les valeurs représentent des caractéristiques sans ordre inhérent.","s":7},{"q":"Quel type de variable est la catégorie d'IMC ?","o":["Qualitative nominale","Qualitative ordinale","Quantitative continue","Quantitative discrète"],"r":1,"e":"Les catégories de classification de l'IMC, comme le niveau d'études, sont des variables qualitatives ordinales : elles ont un ordre logique et séquentiel.","s":7},{"q":"Quelle statistique utilise-t-on pour la moyenne d'une population normale avec σ INCONNU ?","o":["Z, la loi normale centrée réduite","T, la loi de Student","F, la loi de Fisher","Le khi-deux, d'ajustement ou d'indépendance"],"r":1,"e":"Avec σ inconnu et une population normale, T = (X̄ − µ)/(S/√n) suit une loi de Student à n − 1 degrés de liberté. T suit une loi de Student à n − 1 degrés de liberté.","s":7},{"q":"Quel théorème justifie l'usage de Z pour les grands échantillons ?","o":["Le théorème de Bayes","Le Théorème Central Limite","Le théorème de Student","La loi des grands nombres de Fisher"],"r":1,"e":"Pour un grand échantillon (n ≥ 30), le Théorème Central Limite permet d'utiliser Z = (X̄ − µ)/(S/√n) ~ N(0, 1).","s":7},{"q":"À partir de quelle taille d'échantillon le cours applique-t-il le TCL pour la moyenne ?","o":["n ≥ 10","n ≥ 20","n ≥ 30","n ≥ 100"],"r":2,"e":"Le cours retient n ≥ 30 comme seuil de grand échantillon pour appliquer le Théorème Central Limite.","s":7},{"q":"Quel est l'intervalle de confiance pour µ quand σ est connu ?","o":["X̄ ± z(1−α/2) · σ/√n","X̄ ± t(1−α/2, n−1) · S/√n","p̂ ± z(1−α/2) · √[p̂(1−p̂)/n]","X̄ ± σ"],"r":0,"e":"Avec σ connu et une population normale, l'intervalle de confiance est X̄ ± z(1−α/2) · σ/√n.","s":7},{"q":"Quel est l'intervalle de confiance pour une proportion (n > 30) ?","o":["p̂ ± z(1−α/2) · σ/√n","p̂ ± z(1−α/2) · √[p̂(1 − p̂)/n]","p̂ ± t(1−α/2, n−1) · S/√n","p̂ ± p̂/n"],"r":1,"e":"Pour n > 30, l'intervalle de confiance de la proportion est p̂ ± z(1−α/2) · √[p̂(1 − p̂)/n].","s":7},{"q":"Comment s'écrit l'hypothèse nulle d'un test sur la moyenne ?","o":["H0 : µ ≠ µ0","H0 : µ = µ0","H0 : µ > µ0","H0 : µ < µ0"],"r":1,"e":"L'hypothèse nulle s'écrit H0 : µ = µ0 ; l'alternative peut être bilatérale (µ ≠ µ0), unilatérale droite (µ > µ0) ou gauche (µ < µ0).","s":7},{"q":"Quelle est la règle de rejet d'un test BILATÉRAL avec la statistique Z ?","o":["Rejeter H0 si Z > z(1−α)","Rejeter H0 si |Z| > z(1−α/2)","Rejeter H0 si Z < −z(1−α)","Rejeter H0 si Z = 0"],"r":1,"e":"Pour un test bilatéral, on rejette H0 si |Z| > z(1−α/2) ; pour un unilatéral droit si Z > z(1−α) et gauche si Z < −z(1−α).","s":7},{"q":"Quelle statistique utilise-t-on pour deux échantillons indépendants, variances inconnues mais ÉGALES ?","o":["Z, avec les variances des populations","T, avec une variance combinée","T de Welch, à degrés approchés","F de Fisher, sur les variances"],"r":1,"e":"Avec des variances inconnues mais égales, on utilise la variance combinée Sp² et un T à n1 + n2 − 2 degrés de liberté. T suit alors une loi à n1 + n2 − 2 degrés de liberté (variance pooled).","s":7},{"q":"Comment se calcule la variance combinée (pooled) ?","o":["[(n1−1)S1² + (n2−1)S2²] / (n1 + n2 − 2)","[(n1+1)S1² + (n2+1)S2²] / (n1 + n2 + 2)","S1²/n1 + S2²/n2","(n1 S1² + n2 S2²) / (n1 + n2)"],"r":0,"e":"La variance combinée est Sp² = [(n1 − 1)S1² + (n2 − 1)S2²] / (n1 + n2 − 2).","s":7},{"q":"Quel test utilise-t-on quand les variances sont inconnues et DIFFÉRENTES ?","o":["Le test Z, sur des variances connues","Le test T de Welch","Le test F de Fisher","Le test T apparié"],"r":1,"e":"Avec des variances inconnues et différentes, on utilise le T de Welch, dont les degrés de liberté ν sont approchés par une formule spécifique. Ses degrés de liberté sont approchés par une formule spécifique.","s":7},{"q":"Comment traite-t-on des échantillons appariés ?","o":["En comparant directement les deux moyennes","En testant la moyenne des différences","En calculant la variance combinée","En appliquant le test F de Fisher"],"r":1,"e":"Pour des observations appariées (échantillons dépendants), on définit les différences Di = Xi − Yi, puis on teste avec T (loi normale, variance inconnue) ou Z (n > 30). On définit Di = Xi − Yi, puis on teste avec T ou Z.","s":7},{"q":"Quelle statistique sert au test d'égalité des variances ?","o":["Z, centrée réduite","T, de Student","F, de Fisher","Le khi-deux"],"r":2,"e":"Le test d'égalité des variances utilise F = S1²/S2², qui suit une loi de Fisher à (n1 − 1, n2 − 1) degrés de liberté. F = S1²/S2².","s":7},{"q":"Quelle loi suit la statistique F du test d'égalité des variances ?","o":["Une loi normale","Une loi de Student","Une loi de Fisher","Une loi uniforme continue"],"r":2,"e":"F = S1²/S2² suit une loi de Fisher à n1 − 1 et n2 − 1 degrés de liberté. Elle a (n1 − 1, n2 − 1) degrés de liberté.","s":7},{"q":"Quelle statistique utilise-t-on pour tester une proportion sur un grand échantillon ?","o":["Z","T","F","Le khi-deux"],"r":0,"e":"Le récapitulatif du cours indique la statistique Z pour le test de proportion sur grand échantillon.","s":7},{"q":"Quels logiciels le cours recommande-t-il ?","o":["Excel, SPSS et RStudio","MATLAB, Python et SAS","Stata, Minitab et JMP","Word, PowerPoint et Access"],"r":0,"e":"Les logiciels recommandés sont Excel, SPSS et RStudio.","s":7},{"q":"La biostatistique se définit comme :","o":["L'étude des probabilités pures, en mathématiques","La statistique appliquée à la biologie et à la santé","La collecte des données hospitalières","L'analyse des seuls essais cliniques"],"r":1,"e":"Le cours donne pour exemple l'effet d'un traitement sur l'échelle Activities-specific Balance Confidence. La statistique générale est, elle, la science du recueil et de l'analyse des données.","s":7},{"q":"Parmi les objectifs de l'échantillonnage, le cours cite :","o":["Coût et terrain réduits, précision accrue","L'exhaustivité, sur toute la population","La rapidité de publication des résultats","La simplicité des calculs, à la main"],"r":0,"e":"Contre-intuitivement, bien échantillonner peut donner une meilleure précision qu'un recensement bâclé : mieux vaut mesurer soigneusement peu que mal beaucoup. Les méthodes sont aussi optimisées.","s":7},{"q":"Un paramètre statistique se caractérise comme :","o":["Une fonction de l'échantillon, aléatoire et variable","Une valeur fixe et inconnue de la population","Une valeur numérique observée","Une variable aléatoire, mesurée"],"r":1,"e":"Il se note µ, σ², σ, p. L'estimateur, noté X̄, S², S, p̂, est une fonction de l'échantillon, donc une variable aléatoire.","s":7},{"q":"L'estimation se distingue de l'estimateur parce qu'elle est :","o":["Une variable aléatoire, qui varie selon l'échantillon","La valeur numérique observée sur l'échantillon","Un paramètre de la population, fixe","Une hypothèse, à tester"],"r":1,"e":"On la note en minuscules : x̄, s², s, p̂. L'estimateur en majuscules désigne la règle de calcul, l'estimation son résultat sur un échantillon donné.","s":7},{"q":"Dans l'exemple de l'hémoglobine glyquée, µ désigne :","o":["La valeur observée chez un patient","La moyenne de la population","L'estimateur calculé sur l'échantillon","La caractéristique mesurée"],"r":1,"e":"X est la caractéristique, X̄ l'estimateur calculé à partir de l'échantillon, x̄ la valeur numérique observée, et xᵢ la valeur de chaque élément.","s":7},{"q":"Le nombre de médicaments pris par un patient est une variable :","o":["Quantitative discrète","Quantitative continue","Qualitative nominale","Qualitative ordinale"],"r":0,"e":"Les variables discrètes représentent des comptages en valeurs entières. Le poids, la taille et l'âge sont des variables continues.","s":7},{"q":"Le groupe sanguin est une variable :","o":["Quantitative discrète","Quantitative continue","Qualitative nominale","Qualitative ordinale"],"r":2,"e":"Les variables nominales n'ont pas d'ordre inhérent, à la différence des ordinales comme les catégories d'IMC ou le niveau d'études.","s":7},{"q":"Les catégories d'indice de masse corporelle constituent une variable :","o":["Quantitative continue","Qualitative nominale","Qualitative ordinale","Quantitative discrète"],"r":2,"e":"Elles possèdent un ordre logique et séquentiel, ce qui autorise certains traitements statistiques interdits aux variables nominales.","s":7},{"q":"La variance d'un échantillon se calcule en divisant par :","o":["n","n − 1","n + 1","N"],"r":1,"e":"C'est le piège classique signalé par le cours : la variance de la population se divise par N, celle de l'échantillon par n − 1.","s":7},{"q":"Pour l'échantillon 3, 7, 8, 10, 11, la moyenne vaut :","o":["7,0","7,8","8,0","8,2"],"r":1,"e":"La somme fait 39, divisée par 5 éléments. La variance correspondante, calculée avec n − 1 = 4 au dénominateur, vaut 14,70.","s":7},{"q":"Sur 10 individus dont 4 possèdent la caractéristique d'intérêt, la proportion estimée est :","o":["0,04","0,4","4","40"],"r":1,"e":"La proportion p̂ se calcule comme x/n. Elle s'exprime entre 0 et 1, et se convertit ensuite en pourcentage si besoin.","s":7},{"q":"Quand σ est connu et la population normale, l'inférence sur µ utilise :","o":["La loi normale réduite, Z","La loi de Student, T","La loi de Fisher, F","La loi du khi-deux"],"r":0,"e":"Si σ est inconnu et la population normale, on utilise le T de Student à n − 1 degrés de liberté ; pour n ≥ 30, le Z s'applique par le théorème central limite. La loi normale est centrée réduite.","s":7},{"q":"Le théorème central limite permet d'utiliser la loi normale :","o":["Quel que soit l'effectif, même petit","Pour un grand échantillon, quelle que soit la loi","Uniquement si la population suit une loi normale","Uniquement pour les proportions, en épidémiologie descriptive"],"r":1,"e":"C'est ce qui rend les méthodes normales si largement applicables : la distribution de la moyenne tend vers la normale même si les données ne le sont pas. Un grand échantillon correspond à n ≥ 30.","s":7},{"q":"L'intervalle de confiance de la moyenne avec σ inconnu et population normale s'écrit :","o":["X̄ ± z(1−α/2) · σ/√n","X̄ ± t(1−α/2, n−1) · S/√n","X̄ ± t(α/2, n) · σ/√n","p̂ ± z · √[p̂(1−p̂)/n]"],"r":1,"e":"La dernière formule est celle de l'intervalle de confiance d'une proportion, valable pour n supérieur à 30.","s":7},{"q":"Une hypothèse alternative unilatérale droite s'écrit :","o":["µ ≠ µ₀","µ > µ₀","µ < µ₀","µ = µ₀"],"r":1,"e":"H₀ pose toujours l'égalité µ = µ₀. L'alternative peut être bilatérale, unilatérale droite ou unilatérale gauche, selon la question posée.","s":7},{"q":"Pour comparer deux populations indépendantes à variances inconnues mais égales, on utilise :","o":["Un Z, sur variances connues","Un T, avec une variance combinée","Le T de Welch, approché","Une loi de Fisher, F"],"r":1,"e":"Si les variances sont inconnues et différentes, on recourt au T de Welch ; si elles sont connues ou les échantillons grands, au Z. À n₁ + n₂ − 2 degrés de liberté.","s":7},{"q":"Pour des échantillons appariés, la démarche consiste à :","o":["Comparer directement les deux moyennes, en parallèle","Tester la moyenne des différences, par T ou Z","Calculer une loi de Fisher, F","Utiliser un khi-deux, d'indépendance"],"r":1,"e":"On se ramène ainsi à un problème à un seul échantillon : celui des différences. Le Z s'emploie si n dépasse 30. On définit Dᵢ = Xᵢ − Yᵢ.","s":7},{"q":"Le test d'égalité des variances utilise la statistique :","o":["F = S₁²/S₂², de Fisher","Z = (X̄ − µ)/(σ/√n), normale","T = (X̄ − µ)/(S/√n), de Student","Le khi-deux, d'ajustement aux effectifs"],"r":0,"e":"Ses degrés de liberté sont (n₁ − 1, n₂ − 1). Ce test conditionne le choix entre T à variance combinée et T de Welch.","s":7},{"q":"Parmi les logiciels recommandés par le cours figure :","o":["Excel, SPSS et RStudio","MATLAB, seul, sans autre logiciel","Photoshop, pour les figures","Access, pour les tableaux"],"r":0,"e":"Le choix dépend du niveau d'exigence : Excel pour les calculs simples, SPSS pour l'analyse clinique courante, RStudio pour les traitements avancés et reproductibles.","s":7},{"q":"L'écart-type s'obtient :","o":["En divisant la variance par n","En prenant la racine carrée de la variance","En multipliant la variance par n − 1","En sommant les écarts à la moyenne"],"r":1,"e":"Son intérêt est d'être exprimé dans la même unité que les données, contrairement à la variance qui est en unité au carré.","s":7}]};
